static bool sdl_key_is_escape_or_back(SDL_Keycode key)
{
    if (key == SDLK_ESCAPE)
        return true;
#ifdef SDLK_AC_BACK
    if (key == SDLK_AC_BACK)
        return true;
#endif

    return false;
}

