static int sdl_touch_pane_visible_slot_at(int visible_index)
{
    if (visible_index < 0 || visible_index >= SDL_TOUCH_PANE_VISIBLE_BUTTON_COUNT)
        return -1;

    return g_touch_pane_visible_slots[visible_index];
}

