static void sdl_apply_mobile_default_pane_layout(const SDL_Rect* screen,
    bool has_controller)
{
    struct pane_config selected[MAX_PANE_CONFIGS] = { 0 };
    struct pane_config candidate[MAX_PANE_CONFIGS] = { 0 };
    SDL_Rect panes[PANE_MAX] = { 0 };
    int cell_widths[PANE_MAX] = { 0 };
    int cell_heights[PANE_MAX] = { 0 };
    bool touch_enabled;
    bool have_bottom = false;
    bool inventory_enabled = false;
    bool worn_enabled = false;
    bool allow_right_panes = has_controller;
    int bottom_rows = 0;
    int final_main_cols = 0;
    int final_main_rows = 0;

    if (!screen)
        return;

    config.min_terminal_mode = SDL_MIN_TERMINAL_COMPACT;

    memcpy(selected, pane_config, sizeof(selected));
    sdl_mobile_reset_default_pane_configs(selected, pane_config_count);

    touch_enabled = !has_controller;
    sdl_mobile_set_touch_pane_enabled(selected, pane_config_count,
        touch_enabled);

    config.main_view_scale = sdl_mobile_select_default_scale(screen, selected,
        pane_config_count);

    for (int rows = 4; rows >= 1; rows--) {
        memcpy(candidate, selected, sizeof(candidate));
        sdl_mobile_configure_bottom_wide(candidate, pane_config_count, rows);

        if (!sdl_mobile_layout_fits(screen, config.main_view_scale, candidate,
                pane_config_count, panes, cell_widths, cell_heights, NULL,
                NULL))
            continue;
        if (sdl_mobile_pane_cols(panes, cell_widths, PANE_LOG) < 50)
            continue;

        memcpy(selected, candidate, sizeof(selected));
        have_bottom = true;
        bottom_rows = rows;
        break;
    }

    if (!have_bottom) {
        for (int total_rows = 7; total_rows >= 1; total_rows--) {
            memcpy(candidate, selected, sizeof(candidate));
            sdl_mobile_configure_bottom_narrow(candidate, pane_config_count,
                total_rows);

            if (!sdl_mobile_layout_fits(screen, config.main_view_scale,
                    candidate, pane_config_count, NULL, NULL, NULL, NULL,
                    NULL))
                continue;

            memcpy(selected, candidate, sizeof(selected));
            have_bottom = true;
            bottom_rows = total_rows;
            break;
        }
    }

    if (allow_right_panes) {
        memcpy(candidate, selected, sizeof(candidate));
        sdl_mobile_set_right_panes(candidate, pane_config_count, true, false);
        if (sdl_mobile_layout_fits(screen, config.main_view_scale, candidate,
                pane_config_count, NULL, NULL, NULL, NULL, NULL))
        {
            memcpy(selected, candidate, sizeof(selected));
            inventory_enabled = true;
        }

        if (inventory_enabled) {
            memcpy(candidate, selected, sizeof(candidate));
            sdl_mobile_set_right_panes(candidate, pane_config_count, true, true);
            if (sdl_mobile_layout_fits(screen, config.main_view_scale, candidate,
                    pane_config_count, NULL, NULL, NULL, NULL, NULL))
            {
                memcpy(selected, candidate, sizeof(selected));
                worn_enabled = true;
            }
        }
    }

    memcpy(pane_config, selected, sizeof(selected));
    config.enable_bottom_panes = have_bottom;
    config.enable_right_panes = (inventory_enabled || worn_enabled);

    sdl_mobile_layout_fits(screen, config.main_view_scale, pane_config,
        pane_config_count, panes, cell_widths, cell_heights, &final_main_cols,
        &final_main_rows);

    log_info("Mobile default pane layout: controller=%s touch=%s scale=%d main=%dx%d",
        has_controller ? "yes" : "no",
        touch_enabled ? "on" : "off",
        config.main_view_scale, final_main_cols, final_main_rows);
    if (have_bottom) {
        log_info("Mobile default bottom pane: combined log, %d row%s",
            bottom_rows, (bottom_rows == 1) ? "" : "s");
    } else {
        log_info("Mobile default bottom pane: off");
    }
    log_info("Mobile default right panes: inventory=%s worn=%s",
        inventory_enabled ? "on" : "off",
        worn_enabled ? "on" : "off");
}
#endif

static bool sdl_mobile_maybe_apply_first_start_auto_scale(const char* reason)
{
    SDL_Rect screen;
    int old_scale;
    int max_scale;

    if (!g_mobile_first_start_auto_scale_pending)
        return false;

    screen = sdl_get_layout_screen_rect();
    if (!sdl_rect_has_area(&screen))
        return false;

    old_scale = config.main_view_scale;
    max_scale = sdl_max_scale_for_rect(&screen);
    for (int scale = max_scale; scale > old_scale; scale--) {
        if (!sdl_mobile_layout_fits(&screen, scale, pane_config,
                pane_config_count, NULL, NULL, NULL, NULL, NULL))
            continue;

        config.main_view_scale = scale;
        g_mobile_first_start_auto_scale_pending = false;
        log_info("%s: raised first-start mobile main_view_scale from %d to %d after window layout settled",
            reason ? reason : "startup",
            old_scale, config.main_view_scale);
        return true;
    }

    return false;
}
#endif

static bool sdl_touch_pane_is_config_enabled(void)
{
    for (int i = 0; i < pane_config_count; i++) {
        if (pane_config[i].pane == PANE_TOUCH)
            return pane_config[i].enabled;
    }
    return false;
}

static bool sdl_touch_pane_is_left_placement(void)
{
    for (int i = 0; i < pane_config_count; i++) {
        if (pane_config[i].pane != PANE_TOUCH)
            continue;

        return pane_config[i].where == PLACE_DOUBLE_LEFT
            || pane_config[i].where == PLACE_LEFT;
    }

    return false;
}

static bool sdl_touch_only_mobile_device_active(void)
{
#if SIL_SDL_MOBILE_BUILD
    return g_direct_touch_present
        && g_startup_device_class == SDL_STARTUP_DEVICE_MOBILE_TOUCH
        && !steamdeck_controls_active();
#else
    return false;
#endif
}

static bool sdl_touch_tutorial_device_available(void)
{
    return g_direct_touch_present;
}

static bool sdl_touch_tutorial_full_mode(void)
{
    return sdl_touch_only_mobile_device_active();
}

static bool sdl_touch_pane_uses_mobile_toggle(void)
{
    return sdl_touch_only_mobile_device_active()
        && sdl_touch_pane_is_config_enabled();
}

static bool sdl_touch_pane_mobile_layout_open(void)
{
    if (!sdl_touch_pane_uses_mobile_toggle())
        return true;

    return g_touch_pane_mobile_open;
}

static bool sdl_touch_pane_hidden_mode_active(void)
{
    return screen_startup_touch_pane_hidden_active()
        || screen_touch_pane_hidden_active();
}

static bool sdl_touch_pane_proto_mode_active(void)
{
    return screen_touch_pane_proto_active()
        && sdl_touch_only_mobile_device_active();
}

static bool sdl_touch_pane_proto_slot_allowed(int slot)
{
    switch (slot) {
    case SDL_TOUCH_PANE_ESC_SLOT:
    case SDL_TOUCH_PANE_NORTH_SLOT:
    case SDL_TOUCH_PANE_WEST_SLOT:
    case SDL_TOUCH_PANE_CENTER_SLOT:
    case SDL_TOUCH_PANE_EAST_SLOT:
    case SDL_TOUCH_PANE_SOUTH_SLOT:
        return true;
    default:
        return false;
    }
}

static bool sdl_touch_pane_slot_visible_in_current_mode(int slot)
{
    return !sdl_touch_pane_proto_mode_active()
        || sdl_touch_pane_proto_slot_allowed(slot);
}

static int sdl_touch_pane_proto_binding_for_slot(int slot)
{
    switch (slot) {
    case SDL_TOUCH_PANE_ESC_SLOT: return ESCAPE;
    case SDL_TOUCH_PANE_NORTH_SLOT: return '8';
    case SDL_TOUCH_PANE_WEST_SLOT: return '4';
    case SDL_TOUCH_PANE_CENTER_SLOT: return INPUT_BIND_CONFIRM;
    case SDL_TOUCH_PANE_EAST_SLOT: return '6';
    case SDL_TOUCH_PANE_SOUTH_SLOT: return '2';
    default: return GAMEPAD_BIND_NONE;
    }
}

static void sdl_touch_pane_refresh_after_layout_toggle(void)
{
    if (p_ptr && character_generated && !character_icky) {
        p_ptr->update |= PU_PANEL;
        p_ptr->redraw |= PR_BASIC | PR_EXTRA | PR_MAP | PR_DEPTH;
        handle_stuff();
        if (Term)
            Term_fresh();
        g_state.need_present = true;
        return;
    }

    sdl_request_redraw();
}

static void sdl_touch_pane_set_mobile_open(bool open)
{
    if (!sdl_touch_pane_uses_mobile_toggle())
        return;
    if (g_touch_pane_mobile_open == open)
        return;

    g_touch_pane_mobile_open = open;
    if (!open) {
        sdl_touch_pane_cancel_press();
    } else {
        sdl_touch_zone_cancel_press();
        sdl_touch_top_panel_cancel_press();
    }

    if (g_state.window) {
        sdl_resize_for_current_layout();
        sdl_touch_pane_refresh_after_layout_toggle();
    } else {
        g_state.need_present = true;
    }
}

static bool sdl_touch_pane_panel_is_valid(int panel)
{
    return (panel >= 0 && panel < SDL_TOUCH_PANE_PANEL_COUNT);
}

static int sdl_touch_pane_active_panel(void)
{
    return g_touch_pane_second_panel ? SDL_TOUCH_PANE_PANEL_SECOND : SDL_TOUCH_PANE_PANEL_MAIN;
}

static int sdl_touch_pane_other_panel(int panel)
{
    return (panel == SDL_TOUCH_PANE_PANEL_SECOND) ? SDL_TOUCH_PANE_PANEL_MAIN
                                                  : SDL_TOUCH_PANE_PANEL_SECOND;
}

static int sdl_touch_pane_raw_binding_for_panel(int panel, int index)
{
    if (!sdl_touch_pane_panel_is_valid(panel))
        return GAMEPAD_BIND_NONE;
    if (index < 0 || index >= SDL_TOUCH_PANE_BUTTON_COUNT)
        return GAMEPAD_BIND_NONE;

    if (panel == SDL_TOUCH_PANE_PANEL_SECOND)
        return config.touch_pane_second_bindings[index];

    return config.touch_pane_bindings[index];
}

static int sdl_touch_pane_effective_binding_for_panel(int panel, int index)
{
    int binding;

    if (sdl_touch_pane_proto_mode_active())
        return sdl_touch_pane_proto_binding_for_slot(index);

    binding = sdl_touch_pane_raw_binding_for_panel(panel, index);
    if (panel == SDL_TOUCH_PANE_PANEL_SECOND && binding == TOUCH_PANE_BIND_INHERIT)
        return config.touch_pane_bindings[index];

    return binding;
}

static bool sdl_query_direct_touch_present(void)
{
#if SIL_SDL_MOBILE_BUILD
    return true;
#elif defined(SDL_PLATFORM_WINDOWS)
    int digitizer = GetSystemMetrics(SM_DIGITIZER);
    bool ready = (digitizer & NID_READY) != 0;
    bool has_touch = (digitizer & (NID_INTEGRATED_TOUCH | NID_EXTERNAL_TOUCH)) != 0;

    log_debug("Windows digitizer flags: 0x%x", digitizer);
    return ready && has_touch;
#else
    SDL_TouchID* devices;
    int count = 0;
    bool present = false;

    devices = SDL_GetTouchDevices(&count);
    if (!devices)
        return false;

    for (int i = 0; i < count; i++) {
        if (devices[i] == SDL_MOUSE_TOUCHID || devices[i] == SDL_PEN_TOUCHID)
            continue;
        if (SDL_GetTouchDeviceType(devices[i]) == SDL_TOUCH_DEVICE_DIRECT) {
            present = true;
            break;
        }
    }

    SDL_free(devices);
    return present;
#endif
}

static bool sdl_refresh_direct_touch_present(void)
{
    bool present = sdl_query_direct_touch_present();
    bool changed = (g_direct_touch_present != present);

    g_direct_touch_present = present;
    return changed;
}

static void sdl_note_touch_event_device(SDL_TouchID touch_id)
{
    if (g_direct_touch_present)
        return;
    if (touch_id == SDL_MOUSE_TOUCHID || touch_id == SDL_PEN_TOUCHID)
        return;
    if (SDL_GetTouchDeviceType(touch_id) != SDL_TOUCH_DEVICE_DIRECT)
        return;

    g_direct_touch_present = true;
    g_touch_mouse_fallback_active = false;
    sdl_update_cursor_visibility();
    sdl_refresh_supporting_panes_layout();
}

static void sdl_update_cursor_visibility(void)
{
    bool show_cursor = config.mouse_enabled
        && !(config.fullscreen && g_direct_touch_present);

    if (show_cursor)
        SDL_ShowCursor();
    else
        SDL_HideCursor();
}

static void sdl_log_mouse_devices(void)
{
    int count = 0;
    SDL_MouseID* mice = SDL_GetMice(&count);

    if (!mice) {
        log_debug("SDL_GetMice failed: %s", SDL_GetError());
        return;
    }

    log_info("SDL_GetMice returned %d mouse device%s",
        count, (count == 1) ? "" : "s");
    for (int i = 0; i < count; i++) {
        const char* name = SDL_GetMouseNameForID(mice[i]);

        log_info("Mouse device id %u (%s)",
            (unsigned)mice[i], (name && name[0]) ? name : "unnamed");
    }

    SDL_free(mice);
}

static int sdl_build_active_pane_config(struct pane_config* active, bool include_side,
    bool include_bottom, bool touch_only)
{
    int active_count = 0;
    bool proto_touch = sdl_touch_pane_proto_mode_active();

    if (proto_touch)
        sdl_ensure_touch_pane_config_present();

    for (int i = 0; i < pane_config_count && active_count < MAX_PANE_CONFIGS; i++) {
        enum pane_placement where = pane_config[i].where;
        bool is_touch_pane = (pane_config[i].pane == PANE_TOUCH);
        bool is_status_pane = (pane_config[i].pane == PANE_STATUS);
        bool is_left_panel = (pane_config[i].pane == PANE_LEFT_PANEL);
        bool is_depth_pane = (pane_config[i].pane == PANE_DEPTH);
        bool is_main_menu_pane = (pane_config[i].pane == PANE_MAIN_MENU);
        bool is_description_pane = (pane_config[i].pane == PANE_DESCRIPTION);

        if (touch_only && !is_touch_pane && !is_status_pane
            && !is_left_panel && !is_depth_pane && !is_main_menu_pane
            && !is_description_pane)
        {
            continue;
        }
        if (is_touch_pane && !proto_touch && sdl_touch_pane_hidden_mode_active())
            continue;
        if (is_touch_pane && !proto_touch && !sdl_touch_pane_mobile_layout_open())
            continue;
        if (!is_touch_pane && !is_status_pane && !is_left_panel
            && !is_depth_pane
            && !is_main_menu_pane
            && !is_description_pane)
        {
            if (pane_placement_is_side(where) && !include_side)
                continue;
            if (pane_placement_is_bottom(where) && !include_bottom)
                continue;
        }

        active[active_count] = pane_config[i];
        if (is_touch_pane && proto_touch) {
            active[active_count].enabled = true;
            if (!pane_placement_is_side(active[active_count].where))
                active[active_count].where = PLACE_DOUBLE_RIGHT;
        }
        active_count++;
    }

    return active_count;
}

static int sdl_configured_main_view_scale(void)
{
    int scale = config.main_view_scale;

    return sdl_clamp_main_view_scale_platform_bounds(scale,
        config.min_terminal_mode);
}

static int sdl_main_view_layout_scale(void)
{
    int scale = g_main_view_layout_scale_override;

    if (scale <= 0)
        scale = g_terminal_menu_scale_override;
    if (scale <= 0)
        scale = sdl_configured_main_view_scale();

    return sdl_clamp_main_view_scale_platform_bounds(scale,
        config.min_terminal_mode);
}

static bool sdl_main_view_zoom_keep_for_saved_screen(void)
{
    return g_unified_look_active;
}

static int sdl_current_main_view_scale(void)
{
    int scale;

    if (g_main_view_layout_scale_override > 0)
        scale = g_main_view_layout_scale_override;
    else if (g_terminal_menu_scale_override > 0)
        scale = g_terminal_menu_scale_override;
    else if (g_main_view_zoom_scale > 0) {
        scale = g_main_view_zoom_scale;
        if (scale < sdl_main_view_scale_floor())
            scale = sdl_main_view_scale_floor();
        if (scale > SDL_MAIN_VIEW_MAX_SCALE)
            scale = SDL_MAIN_VIEW_MAX_SCALE;
        return scale;
    } else {
        scale = config.main_view_scale;
    }

    return sdl_clamp_main_view_scale_platform_bounds(scale,
        config.min_terminal_mode);
}

static int sdl_auto_font_size_from_main(int numerator, int denominator)
{
    float system_scale = (g_state.system_scale > 0.0f) ? g_state.system_scale : 1.0f;
    int main_cell_h_px = sdl_configured_main_view_scale() * TILE_SIZE;
    int main_font_size;
    int size;

    if (g_auto_aux_main_cell_h_override > 0)
        main_cell_h_px = g_auto_aux_main_cell_h_override;

    main_font_size = (int)((float)main_cell_h_px / system_scale + 0.5f);
    size = (main_font_size * numerator + denominator - 1) / denominator;

    if (size >= main_font_size && main_font_size > 8)
        size = main_font_size - 1;

    if (size < 8)
        size = 8;
    if (size > 48)
        size = 48;

    return size;
}

static int sdl_auto_aux_view_font_size(void)
{
    return sdl_auto_font_size_from_main(2, 3);
}

static int sdl_auto_pane_font_size(enum pane_type type)
{
    if (type == PANE_STATUS)
        return sdl_auto_font_size_from_main(1, 2);
    if (type == PANE_LEFT_PANEL || type == PANE_MAIN_MENU)
        return sdl_auto_font_size_from_main(3, 4);
    if (type == PANE_DESCRIPTION)
        return sdl_auto_font_size_from_main(2, 3);

    return sdl_auto_aux_view_font_size();
}

static int sdl_resolve_aux_view_font_size(int requested_size)
{
    int size = requested_size;

    if (size <= 0)
        size = sdl_auto_aux_view_font_size();
    if (size < 8)
        size = 8;
    if (size > 48)
        size = 48;

    return size;
}

static int sdl_resolve_pane_font_size(enum pane_type type, int requested_size)
{
    int size = requested_size;

    if (size <= 0)
        size = sdl_auto_pane_font_size(type);
    if (size < 8)
        size = 8;
    if (size > 48)
        size = 48;

    return size;
}

static int sdl_effective_pane_font_size_for_config(const struct pane_config* pc)
{
    if (pc && pc->font_size > 0)
        return sdl_resolve_aux_view_font_size(pc->font_size);
    if (pc)
        return sdl_resolve_pane_font_size(pc->pane, config.aux_view_font_size);

    return sdl_resolve_aux_view_font_size(config.aux_view_font_size);
}

static int sdl_effective_pane_font_size_for_type(enum pane_type type)
{
    for (int i = 0; i < pane_config_count; i++) {
        if (pane_config[i].pane == type)
            return sdl_effective_pane_font_size_for_config(&pane_config[i]);
    }

    return sdl_resolve_pane_font_size(type, config.aux_view_font_size);
}

static int sdl_aux_cell_height_for_font_size(int font_size)
{
    int cell_h = (int)(g_state.system_scale * (float)font_size + 0.5f);

    if (cell_h < 1)
        cell_h = 1;

    return cell_h;
}

static int sdl_effective_pane_cell_height_for_config(const struct pane_config* pc)
{
    return sdl_aux_cell_height_for_font_size(
        sdl_effective_pane_font_size_for_config(pc));
}

static int sdl_effective_pane_cell_height_for_type(enum pane_type type)
{
    return sdl_aux_cell_height_for_font_size(
        sdl_effective_pane_font_size_for_type(type));
}

static void sdl_build_supporting_pane_metrics(const struct pane_config* configs,
    int count, int* cell_widths, int* cell_heights)
{
    int default_font_size = sdl_resolve_aux_view_font_size(config.aux_view_font_size);
    int default_cell_h = sdl_aux_cell_height_for_font_size(default_font_size);
    int default_cell_w;

    if (!cell_widths || !cell_heights)
        return;

    if (default_cell_h < 1)
        default_cell_h = 1;
    default_cell_w = default_cell_h / 2;
    if (default_cell_w < 1)
        default_cell_w = 1;

    for (int i = 0; i < PANE_MAX; i++) {
        cell_widths[i] = default_cell_w;
        cell_heights[i] = default_cell_h;
    }

    {
        /* Pane placement is part of the persistent layout.  Runtime zoom only
         * changes how the main term is rendered inside that rectangle. */
        int main_scale = sdl_main_view_layout_scale();

        cell_widths[PANE_MAIN] = main_scale * TILE_SIZE / 2;
        cell_heights[PANE_MAIN] = main_scale * TILE_SIZE;
    }

    for (int i = 0; i < count; i++) {
        enum pane_type type = configs[i].pane;
        int cell_h;

        if (type <= PANE_MAIN || type >= PANE_MAX)
            continue;

        cell_h = sdl_effective_pane_cell_height_for_config(&configs[i]);
        cell_heights[type] = cell_h;
        cell_widths[type] = cell_h / 2;
        if (cell_widths[type] < 1)
            cell_widths[type] = 1;
    }
}

static bool sdl_prune_unusable_panes(struct pane_config* active,
    int active_count, SDL_Rect* panes, const int* cell_widths,
    const int* cell_heights)
{
    bool pruned = false;

    for (int i = 0; i < active_count; i++) {
        struct pane_config* pc = &active[i];
        enum pane_type type = pc->pane;
        SDL_Rect* rect;
        int cell_w;
        int cell_h;
        int cols;
        int rows;
        int min_cols;
        int min_rows;

        if (!pc->enabled)
            continue;
        if (type <= PANE_MAIN || type >= PANE_MAX)
            continue;

        rect = &panes[type];
        if (rect->w <= 0 || rect->h <= 0)
            continue;

        cell_w = cell_widths[type];
        cell_h = cell_heights[type];
        if (cell_w <= 0 || cell_h <= 0) {
            pc->enabled = false;
            *rect = (SDL_Rect){ 0 };
            pruned = true;
            continue;
        }

        cols = rect->w / cell_w;
        rows = rect->h / cell_h;
        if (pane_placement_is_side(pc->where)) {
            min_cols = pane_primary_min_cells(type, pc->where);
            min_rows = pane_secondary_min_cells(type, pc->where);
        } else {
            min_cols = pane_secondary_min_cells(type, pc->where);
            min_rows = pane_primary_min_cells(type, pc->where);
        }

        if (cols >= min_cols && rows >= min_rows)
            continue;

        log_info("Skipping pane %d at (%d,%d) size %dx%d: fits %dx%d cells, needs %dx%d",
            type, rect->x, rect->y, rect->w, rect->h, cols, rows, min_cols, min_rows);
        pc->enabled = false;
        *rect = (SDL_Rect){ 0 };
        pruned = true;
    }

    return pruned;
}

static int sdl_inventory_pane_desired_rows(void)
{
    int rows = 0;

    if (!character_generated || !p_ptr || !inventory)
        return -1;

    for (int i = 0; i < INVEN_PACK; i++) {
        if (inventory[i].k_idx)
            rows = i + 1;
    }

    if (p_ptr->inven_cnt > rows)
        rows = p_ptr->inven_cnt;
    if (rows < 1)
        rows = 1;
    if (rows > INVEN_PACK)
        rows = INVEN_PACK;

    return rows;
}

static bool sdl_inventory_pane_dynamic_configured(void)
{
    if (!character_generated || !p_ptr || !inventory)
        return false;
    if (!config.enable_right_panes)
        return false;

    for (int i = 0; i < pane_config_count; i++) {
        if (pane_config[i].pane != PANE_INVENTORY)
            continue;
        if (!pane_config[i].enabled)
            continue;
        if (!pane_placement_is_side(pane_config[i].where))
            continue;

        return true;
    }

    return false;
}

static void sdl_apply_dynamic_inventory_pane_size(struct pane_config* active,
    int active_count)
{
    int rows = sdl_inventory_pane_desired_rows();

    if (rows < 1)
        return;

    for (int i = 0; i < active_count; i++) {
        if (!active[i].enabled)
            continue;
        if (active[i].pane != PANE_INVENTORY)
            continue;
        if (!pane_placement_is_side(active[i].where))
            continue;

        active[i].rect.rows = rows;
    }
}

static int sdl_supply_pane_desired_rows(void)
{
    int rows;

    if (!character_generated || !p_ptr)
        return -1;

    rows = supplies_entry_count() + 1;
    if (rows < 2)
        rows = 2;
    if (rows > 27)
        rows = 27;

    return rows;
}

static bool sdl_supply_pane_dynamic_configured(void)
{
    if (!character_generated || !p_ptr)
        return false;
    if (!config.enable_right_panes)
        return false;

    for (int i = 0; i < pane_config_count; i++) {
        if (pane_config[i].pane != PANE_SUPPLY)
            continue;
        if (!pane_config[i].enabled)
            continue;
        if (!pane_placement_is_side(pane_config[i].where))
            continue;

        return true;
    }

    return false;
}

static void sdl_apply_dynamic_supply_pane_size(struct pane_config* active,
    int active_count)
{
    int rows = sdl_supply_pane_desired_rows();

    if (rows < 1)
        return;

    for (int i = 0; i < active_count; i++) {
        if (!active[i].enabled)
            continue;
        if (active[i].pane != PANE_SUPPLY)
            continue;
        if (!pane_placement_is_side(active[i].where))
            continue;

        active[i].rect.rows = rows;
    }
}

static int sdl_touch_pane_target_width_px(int pane_height_px)
{
    const int numerator = 40 * SDL_TOUCH_PANE_BUTTON_COLS;
    const int denominator = 39 * SDL_TOUCH_PANE_VISIBLE_BUTTON_ROWS
        + SDL_TOUCH_PANE_BUTTON_COLS;

    if (pane_height_px <= 0)
        return 0;

    return (pane_height_px * numerator + denominator - 1) / denominator;
}

static void sdl_apply_dynamic_auto_pane_sizes(struct pane_config* active,
    int active_count, const SDL_Rect* screen, const int* cell_widths,
    const int* cell_heights, int margin_px)
{
    SDL_Rect temp_panes[PANE_MAX] = { 0 };
    int touch_idx = -1;
    int min_touch_cols;
    int min_touch_width_px;
    int desired_touch_px;
    int desired_touch_cols;
    int max_touch_px;
    int max_touch_cols;
    int min_main_width_px;

    if (!active || active_count <= 0 || !screen || !cell_widths || !cell_heights)
        return;

    sdl_apply_dynamic_inventory_pane_size(active, active_count);
    sdl_apply_dynamic_supply_pane_size(active, active_count);

    for (int i = 0; i < active_count; i++) {
        if (!active[i].enabled)
            continue;
        if (active[i].pane != PANE_TOUCH)
            continue;
        if (!pane_placement_is_side(active[i].where))
            continue;
        if (active[i].rect.cols > 0)
            continue;

        touch_idx = i;
        break;
    }

    if (touch_idx < 0)
        return;

    place_panes(active, active_count, temp_panes, screen, cell_widths,
        cell_heights,
        margin_px);

    if (temp_panes[PANE_TOUCH].w <= 0 || temp_panes[PANE_TOUCH].h <= 0)
        return;

    min_touch_cols = pane_primary_min_cells(PANE_TOUCH, active[touch_idx].where);
    min_touch_width_px = min_touch_cols * cell_widths[PANE_TOUCH] + margin_px;
    desired_touch_px = sdl_touch_pane_target_width_px(temp_panes[PANE_TOUCH].h);
    if (desired_touch_px < min_touch_width_px)
        desired_touch_px = min_touch_width_px;

    desired_touch_cols = (desired_touch_px > margin_px)
        ? ((desired_touch_px - margin_px + cell_widths[PANE_TOUCH] - 1)
            / cell_widths[PANE_TOUCH])
        : min_touch_cols;
    if (desired_touch_cols < min_touch_cols)
        desired_touch_cols = min_touch_cols;

    min_main_width_px = sdl_current_min_terminal_cols() * cell_widths[PANE_MAIN];
    max_touch_px = temp_panes[PANE_MAIN].w + temp_panes[PANE_TOUCH].w
        - min_main_width_px;

    if (max_touch_px >= min_touch_width_px) {
        max_touch_cols = (max_touch_px > margin_px)
            ? ((max_touch_px - margin_px) / cell_widths[PANE_TOUCH])
            : 0;
        if (max_touch_cols < min_touch_cols)
            max_touch_cols = min_touch_cols;
        if (desired_touch_cols > max_touch_cols)
            desired_touch_cols = max_touch_cols;
    }

    active[touch_idx].rect.cols = desired_touch_cols;
}

static void sdl_place_active_panes(const SDL_Rect* screen, SDL_Rect* panes,
    bool include_side, bool include_bottom, bool touch_only)
{
    struct pane_config active[MAX_PANE_CONFIGS] = { 0 };
    int active_count;
    int cell_widths[PANE_MAX] = { 0 };
    int cell_heights[PANE_MAX] = { 0 };
    int margin_px;

    if (!screen || !panes)
        return;

    memset(panes, 0, sizeof(SDL_Rect) * PANE_MAX);

    margin_px = (int)(g_state.system_scale * config.margin);
    active_count = sdl_build_active_pane_config(active, include_side,
        include_bottom, touch_only);
    sdl_build_supporting_pane_metrics(active, active_count, cell_widths,
        cell_heights);
    sdl_apply_dynamic_auto_pane_sizes(active, active_count, screen, cell_widths,
        cell_heights, margin_px);

    for (int attempt = 0; attempt <= active_count; attempt++) {
        place_panes(active, active_count, panes, screen, cell_widths,
            cell_heights, margin_px);
        if (!sdl_prune_unusable_panes(active, active_count, panes, cell_widths,
                cell_heights))
            break;
        memset(panes, 0, sizeof(SDL_Rect) * PANE_MAX);
    }
}

static bool sdl_active_group_has_visible(const struct pane_config* active,
    int active_count, const SDL_Rect* panes, bool side)
{
    for (int i = 0; i < active_count; i++) {
        SDL_Rect rect;
        bool matches;

        if (!active[i].enabled)
            continue;
        matches = side ? pane_placement_is_side(active[i].where)
                       : pane_placement_is_bottom(active[i].where);
        if (!matches)
            continue;

        rect = panes[active[i].pane];
        if (rect.w > 0 && rect.h > 0)
            return true;
    }

    return false;
}

static void sdl_place_active_panes_fitting_main(const SDL_Rect* screen,
    SDL_Rect* panes, bool include_side, bool include_bottom, bool touch_only,
    bool* out_side, bool* out_bottom)
{
    struct pane_config base[MAX_PANE_CONFIGS] = { 0 };
    struct pane_config active[MAX_PANE_CONFIGS] = { 0 };
    int active_count;
    int cell_widths[PANE_MAX] = { 0 };
    int cell_heights[PANE_MAX] = { 0 };
    int margin_px;

    if (out_side)
        *out_side = false;
    if (out_bottom)
        *out_bottom = false;
    if (!screen || !panes)
        return;

    memset(panes, 0, sizeof(SDL_Rect) * PANE_MAX);

    margin_px = (int)(g_state.system_scale * config.margin);
    active_count = sdl_build_active_pane_config(base, include_side,
        include_bottom, touch_only);
    memcpy(active, base, sizeof(struct pane_config) * active_count);
    sdl_build_supporting_pane_metrics(active, active_count, cell_widths,
        cell_heights);
    sdl_apply_dynamic_auto_pane_sizes(active, active_count, screen,
        cell_widths, cell_heights, margin_px);

    for (int attempt = 0; attempt <= active_count; attempt++) {
        place_panes(active, active_count, panes, screen, cell_widths,
            cell_heights, margin_px);
        if (!sdl_prune_unusable_panes(active, active_count, panes,
                cell_widths, cell_heights))
        {
            break;
        }
        memset(panes, 0, sizeof(SDL_Rect) * PANE_MAX);
    }

    if (out_side)
        *out_side = sdl_active_group_has_visible(active, active_count, panes,
            true);
    if (out_bottom)
        *out_bottom = sdl_active_group_has_visible(active, active_count, panes,
            false);
}

static int sdl_bottom_pane_group_rows_for_minimum(const SDL_Rect* panes,
    enum pane_placement where)
{
    int rows = 0;

    if (!panes)
        return 0;

    for (int i = 0; i < pane_config_count; i++) {
        const struct pane_config* pc = &pane_config[i];
        const SDL_Rect* rect;
        int cell_h;
        int pane_rows;

        if (!pc->enabled || pc->where != where)
            continue;
        if (pc->pane <= PANE_MAIN || pc->pane >= PANE_MAX)
            continue;

        rect = &panes[pc->pane];
        if (rect->w <= 0 || rect->h <= 0)
            continue;

        cell_h = sdl_effective_pane_cell_height_for_config(pc);
        if (cell_h <= 0)
            continue;

        pane_rows = rect->h / cell_h;
        if (pane_rows > rows)
            rows = pane_rows;
    }

    return rows;
}

static int sdl_bottom_pane_rows_for_minimum(const SDL_Rect* panes)
{
    return sdl_bottom_pane_group_rows_for_minimum(panes, PLACE_DOUBLE_BOTTOM)
        + sdl_bottom_pane_group_rows_for_minimum(panes, PLACE_BOTTOM);
}

static void sdl_compute_pruned_split_panes_for_mode_ex(const SDL_Rect* screen,
    int mode, int scale, bool aux_follows_candidate_scale, SDL_Rect* panes,
    bool* out_side, bool* out_bottom, int* out_cols, int* out_rows,
    int* out_rows_with_bottom)
{
    SDL_Rect local_panes[PANE_MAX] = { 0 };
    SDL_Rect* target_panes = panes ? panes : local_panes;
    int saved_mode = config.min_terminal_mode;
    int saved_scale = config.main_view_scale;
    int saved_layout_scale_override = g_main_view_layout_scale_override;
    int saved_aux_override = g_auto_aux_main_cell_h_override;
    bool include_side = config.enable_right_panes;
    bool include_bottom = config.enable_bottom_panes;
    int layout_scale;
    int cell_w;
    int cell_h;
    int cols = 0;
    int rows = 0;

    if (panes)
        memset(panes, 0, sizeof(SDL_Rect) * PANE_MAX);
    if (out_side)
        *out_side = include_side;
    if (out_bottom)
        *out_bottom = include_bottom;
    if (out_cols)
        *out_cols = 0;
    if (out_rows)
        *out_rows = 0;
    if (out_rows_with_bottom)
        *out_rows_with_bottom = 0;

    if (!screen || !sdl_rect_has_area(screen) || scale <= 0)
        return;
    if (!sdl_min_terminal_mode_is_valid(mode))
        return;

    /* Temporary zoom changes the rendered main view scale, but pane
     * visibility/layout still follows the saved main scale. */
    layout_scale = aux_follows_candidate_scale
        ? scale
        : sdl_configured_main_view_scale();
    config.min_terminal_mode = mode;
    g_main_view_layout_scale_override = layout_scale;
    if (aux_follows_candidate_scale) {
        config.main_view_scale = scale;
        g_auto_aux_main_cell_h_override = scale * TILE_SIZE;
    } else {
        g_auto_aux_main_cell_h_override = layout_scale * TILE_SIZE;
    }

    cell_w = scale * TILE_SIZE / 2;
    cell_h = scale * TILE_SIZE;
    sdl_place_active_panes_fitting_main(screen, target_panes, include_side,
        include_bottom, false, &include_side, &include_bottom);
    cols = (cell_w > 0)
        ? sdl_main_view_logical_cols_for_visual_cols(
            target_panes[PANE_MAIN].w / cell_w)
        : 0;
    rows = (cell_h > 0) ? target_panes[PANE_MAIN].h / cell_h : 0;
    if (out_rows_with_bottom)
        *out_rows_with_bottom = rows
            + sdl_bottom_pane_rows_for_minimum(target_panes);

    config.min_terminal_mode = saved_mode;
    config.main_view_scale = saved_scale;
    g_main_view_layout_scale_override = saved_layout_scale_override;
    g_auto_aux_main_cell_h_override = saved_aux_override;

    if (out_side)
        *out_side = include_side;
    if (out_bottom)
        *out_bottom = include_bottom;
    if (out_cols)
        *out_cols = cols;
    if (out_rows)
        *out_rows = rows;
}

static void sdl_mark_active_supporting_panes_dirty(const SDL_Rect* panes)
{
    u32b flags = 0L;

    if (!panes || !p_ptr || !op_ptr)
        return;

    for (int i = 1; i < ANGBAND_TERM_MAX && i < PANE_MAX; i++) {
        if (panes[i].w <= 0 || panes[i].h <= 0)
            continue;
        if (!angband_term[i])
            continue;

        flags |= op_ptr->window_flag[i];
    }

    if (flags)
        p_ptr->window |= flags;
}

static bool sdl_hide_supporting_panes_mode_effective(void)
{
    bool explicit_hide = screen_startup_supporting_panes_hidden_active()
        || screen_supporting_panes_hidden_active();

    /* Startup hidden mode must be able to take effect before persistent
     * options have been loaded into op_ptr. */
    if (!explicit_hide && op_ptr
        && !op_ptr->opt[OPT_hide_supporting_panes_fullscreen])
        return false;

    for (int i = 0; i < pane_config_count; i++) {
        enum pane_placement where = pane_config[i].where;

        if (!pane_config[i].enabled)
            continue;
        if (pane_config[i].pane == PANE_MAIN
            || pane_config[i].pane == PANE_TOUCH
            || pane_config[i].pane == PANE_LEFT_PANEL
            || pane_config[i].pane == PANE_STATUS
            || pane_config[i].pane == PANE_DEPTH
            || pane_config[i].pane == PANE_MAIN_MENU
            || pane_config[i].pane == PANE_DESCRIPTION)
        {
            continue;
        }
        if (pane_placement_is_side(where) && !g_active_side_panes)
            continue;
        if (pane_placement_is_bottom(where) && !g_active_bottom_panes)
            continue;

        return true;
    }

    return false;
}

static void sdl_draw_pane_edges(const SDL_Rect* rect, bool draw_left,
    bool draw_top, bool draw_right, bool draw_bottom)
{
    int x1;
    int y1;
    int x2;
    int y2;

    if (!rect || rect->w <= 0 || rect->h <= 0)
        return;

    x1 = rect->x;
    y1 = rect->y;
    x2 = rect->x + rect->w - 1;
    y2 = rect->y + rect->h - 1;

    if (x2 < x1 || y2 < y1)
        return;

    if (draw_top)
        SDL_RenderFillRect(g_state.renderer, &(SDL_FRect){
            .x = (float)x1,
            .y = (float)y1,
            .w = (float)(x2 - x1 + 1),
            .h = 1.0f,
        });
    if (draw_bottom)
        SDL_RenderFillRect(g_state.renderer, &(SDL_FRect){
            .x = (float)x1,
            .y = (float)y2,
            .w = (float)(x2 - x1 + 1),
            .h = 1.0f,
        });

    {
        int top_offset = draw_top ? 1 : 0;
        int bottom_offset = draw_bottom ? 1 : 0;
        int edge_height = y2 - y1 + 1 - top_offset - bottom_offset;

        if (edge_height > 0 && draw_left)
            SDL_RenderFillRect(g_state.renderer, &(SDL_FRect){
                .x = (float)x1,
                .y = (float)(y1 + top_offset),
                .w = 1.0f,
                .h = (float)edge_height,
            });
        if (edge_height > 0 && draw_right)
            SDL_RenderFillRect(g_state.renderer, &(SDL_FRect){
                .x = (float)x2,
                .y = (float)(y1 + top_offset),
                .w = 1.0f,
                .h = (float)edge_height,
            });
    }
}

static bool sdl_should_show_supporting_panes(void)
{
    if (!sdl_hide_supporting_panes_mode_effective())
        return true;
    if (screen_startup_supporting_panes_hidden_active())
        return false;
    if (screen_supporting_panes_hidden_active())
        return false;
    if (screen_saved_fullscreen_active())
        return false;

    return true;
}

static bool sdl_layout_matches_supporting_pane_visibility(void)
{
    bool show_supporting_panes = sdl_should_show_supporting_panes();

    if (g_supporting_panes_layout_visible != show_supporting_panes)
        return false;
    if (g_touch_pane_hidden_layout_active != sdl_touch_pane_hidden_mode_active())
        return false;
    if (g_touch_pane_proto_layout_active != sdl_touch_pane_proto_mode_active())
        return false;
    if (show_supporting_panes && sdl_inventory_pane_dynamic_configured()) {
        int rows = sdl_inventory_pane_desired_rows();

        if (rows > 0 && g_inventory_pane_layout_rows != rows)
            return false;
    }
    if (show_supporting_panes && sdl_supply_pane_dynamic_configured()) {
        int rows = sdl_supply_pane_desired_rows();

        if (rows > 0 && g_supply_pane_layout_rows != rows)
            return false;
    }

    return true;
}

static void sdl_compute_display_panes(SDL_Rect* panes)
{
    SDL_Rect screen;

    if (!panes)
        return;

    if (!g_state.window || sdl_should_show_supporting_panes()) {
        memcpy(panes, g_pane_rects, sizeof(g_pane_rects));
        return;
    }

    screen = sdl_get_layout_screen_rect();
    sdl_place_active_panes(&screen, panes, g_active_side_panes,
        g_active_bottom_panes, true);
}

static int sdl_max_scale_for_rect_mode(const SDL_Rect* rect, int mode)
{
    int min_cols;
    int min_rows;
    int max_scale_w;
    int max_scale_h;
    int max_scale;

    if (!rect)
        return SDL_MAIN_VIEW_MIN_SCALE;

    min_cols = sdl_min_terminal_cols_for_mode(mode);
    min_rows = sdl_min_terminal_rows_for_mode(mode);
    max_scale_w = (rect->w / min_cols) * 2 / TILE_SIZE;
    max_scale_h = rect->h / min_rows / TILE_SIZE;
    max_scale = (max_scale_w < max_scale_h) ? max_scale_w : max_scale_h;

    if (max_scale < SDL_MAIN_VIEW_MIN_SCALE)
        max_scale = SDL_MAIN_VIEW_MIN_SCALE;
    if (max_scale > SDL_MAIN_VIEW_MAX_SCALE)
        max_scale = SDL_MAIN_VIEW_MAX_SCALE;

    return max_scale;
}

static int sdl_max_scale_for_rect(const SDL_Rect* rect)
{
    return sdl_max_scale_for_rect_mode(rect, config.min_terminal_mode);
}

static bool sdl_apply_default_main_scale_for_layout(const char* reason)
{
    SDL_Rect screen;
    int old_scale;
    int new_scale;

    if (!g_state.window)
        return false;

    sdl_refresh_safe_area();
    screen = sdl_get_layout_screen_rect();
    if (!sdl_rect_has_area(&screen))
        return false;

    old_scale = config.main_view_scale;
    new_scale = sdl_max_scale_for_layout(&screen, config.min_terminal_mode);
    new_scale = sdl_clamp_main_view_scale_floor(new_scale,
        config.min_terminal_mode);

    config.main_view_scale = new_scale;
    g_main_view_zoom_scale = 0;

    if (old_scale != new_scale) {
        log_info("%s: default main_view_scale changed from %d to %d for layout %dx%d without supporting panes",
            reason ? reason : "startup", old_scale, new_scale,
            screen.w, screen.h);
        return true;
    }

    log_info("%s: default main_view_scale %d fits layout %dx%d without supporting panes",
        reason ? reason : "startup", new_scale, screen.w, screen.h);
    return false;
}

static int sdl_max_scale_for_layout(const SDL_Rect* screen, int mode)
{
    int min_cols;
    int min_rows;

    if (!screen || !sdl_rect_has_area(screen))
        return SDL_MAIN_VIEW_MIN_SCALE;
    if (!sdl_min_terminal_mode_is_valid(mode))
        return SDL_MAIN_VIEW_MIN_SCALE;

    min_cols = sdl_min_terminal_cols_for_mode(mode);
    min_rows = sdl_min_terminal_rows_for_mode(mode);

    for (int scale = SDL_MAIN_VIEW_MAX_SCALE;
         scale >= SDL_MAIN_VIEW_MIN_SCALE; scale--) {
        int cols = 0;
        int rows = 0;
        int rows_with_bottom = 0;

        sdl_compute_pruned_split_panes_for_mode_ex(screen, mode, scale, true,
            NULL, NULL, NULL, &cols, &rows, &rows_with_bottom);
        if (cols >= min_cols && rows_with_bottom >= min_rows)
            return scale;
    }

    return SDL_MAIN_VIEW_MIN_SCALE;
}

enum { SDL_MAIN_VIEW_ZOOM_MIN_MAP_SQUARES = 10 };

static int sdl_main_view_terminal_cols_for_map_squares(int map_cols)
{
    int tile_cols = use_bigtile ? 2 : 1;

    if (map_cols < 1)
        map_cols = 1;

    return COL_MAP + 1 + map_cols * tile_cols;
}

static int sdl_main_view_terminal_rows_for_map_squares(int map_rows)
{
    if (map_rows < 1)
        map_rows = 1;

    return map_rows;
}

static int sdl_main_view_map_cols_for_terminal_cols(int cols)
{
    int tile_cols = use_bigtile ? 2 : 1;
    int map_cols = (cols - COL_MAP - 1) / tile_cols;

    return (map_cols > 0) ? map_cols : 0;
}

static int sdl_main_view_map_rows_for_terminal_rows(int rows)
{
    int map_rows = rows;

    return (map_rows > 0) ? map_rows : 0;
}

static int sdl_max_main_view_zoom_scale_for_layout(const SDL_Rect* screen,
    int mode)
{
    if (!screen || !sdl_rect_has_area(screen))
        return SDL_MAIN_VIEW_MIN_SCALE;
    if (!sdl_min_terminal_mode_is_valid(mode))
        return SDL_MAIN_VIEW_MIN_SCALE;

    for (int scale = SDL_MAIN_VIEW_MAX_SCALE;
         scale >= SDL_MAIN_VIEW_MIN_SCALE; scale--) {
        int cols = 0;
        int rows = 0;
        int map_cols;
        int map_rows;

        sdl_compute_pruned_split_panes_for_mode_ex(screen, mode, scale, false,
            NULL, NULL, NULL, &cols, &rows, NULL);
        map_cols = sdl_main_view_map_cols_for_terminal_cols(cols);
        map_rows = sdl_main_view_map_rows_for_terminal_rows(rows);
        if (map_cols >= SDL_MAIN_VIEW_ZOOM_MIN_MAP_SQUARES
            || map_rows >= SDL_MAIN_VIEW_ZOOM_MIN_MAP_SQUARES)
        {
            return scale;
        }
    }

    return SDL_MAIN_VIEW_MIN_SCALE;
}

static int sdl_min_main_view_zoom_scale_for_layout(const SDL_Rect* screen,
    int mode)
{
    int floor = sdl_main_view_scale_floor_for_mode(mode);

    if (!screen || !sdl_rect_has_area(screen))
        return floor;
    if (!sdl_min_terminal_mode_is_valid(mode))
        return floor;

    return floor;
}

static int sdl_max_scale_for_window_mode(int mode)
{
    struct sdl_config saved_config = config;
    struct pane_config saved_panes[MAX_PANE_CONFIGS];
    SDL_Rect screen;
    int saved_pane_count = pane_config_count;
    int max_scale = SDL_MAIN_VIEW_MIN_SCALE;

    memcpy(saved_panes, pane_config, sizeof(saved_panes));

    config.min_terminal_mode = mode;
    sdl_apply_stored_pane_profile(mode);
    config.min_terminal_mode = mode;

    sdl_refresh_safe_area();
    screen = sdl_get_layout_screen_rect();
    if (sdl_rect_has_area(&screen))
        max_scale = sdl_max_scale_for_layout(&screen, mode);

    config = saved_config;
    pane_config_count = saved_pane_count;
    memcpy(pane_config, saved_panes, sizeof(saved_panes));

    return max_scale;
}

static bool sdl_mode_scale_fits_window(const SDL_Rect* screen, int mode,
    int scale, int* cols, int* rows)
{
    struct sdl_config saved_config = config;
    struct pane_config saved_panes[MAX_PANE_CONFIGS];
    SDL_Rect panes[PANE_MAX];
    int saved_pane_count = pane_config_count;
    int local_cols = 0;
    int local_rows = 0;
    int local_rows_with_bottom = 0;
    bool fits = false;

    if (!screen || !sdl_rect_has_area(screen) || scale <= 0)
        return false;

    memcpy(saved_panes, pane_config, sizeof(saved_panes));

    config.min_terminal_mode = mode;
    sdl_apply_stored_pane_profile(mode);
    config.min_terminal_mode = mode;
    sdl_compute_pruned_split_panes_for_mode_ex(screen, mode, scale, true,
        panes, NULL, NULL, &local_cols, &local_rows, &local_rows_with_bottom);
    fits = (local_cols >= sdl_min_terminal_cols_for_mode(mode)
        && local_rows_with_bottom >= sdl_min_terminal_rows_for_mode(mode));

    config = saved_config;
    pane_config_count = saved_pane_count;
    memcpy(pane_config, saved_panes, sizeof(saved_panes));

    if (cols)
        *cols = local_cols;
    if (rows)
        *rows = local_rows;

    return fits;
}

static void sdl_ensure_window_size_for_min_terminal(const SDL_Rect* screen,
    int* window_width, int* window_height)
{
    int min_width;
    int min_height;
    int min_scale;

    if (!screen || !window_width || !window_height || config.fullscreen)
        return;

    min_scale = sdl_main_view_scale_floor();
    min_width = sdl_current_min_terminal_cols()
        * (min_scale * TILE_SIZE / 2);
    min_height = sdl_current_min_terminal_rows()
        * (min_scale * TILE_SIZE);

    if (min_width < 1)
        min_width = 1;
    if (min_height < 1)
        min_height = 1;

    if (screen->w > 0 && min_width > screen->w)
        min_width = screen->w;
    if (screen->h > 0 && min_height > screen->h)
        min_height = screen->h;

    if (*window_width < min_width) {
        log_info("Increasing initial window width from %d to %d to fit minimum terminal %dx%d (%s)",
            *window_width, min_width,
            sdl_current_min_terminal_cols(), sdl_current_min_terminal_rows(),
            sdl_min_terminal_mode_name(config.min_terminal_mode));
        *window_width = min_width;
    }

    if (*window_height < min_height) {
        log_info("Increasing initial window height from %d to %d to fit minimum terminal %dx%d (%s)",
            *window_height, min_height,
            sdl_current_min_terminal_cols(), sdl_current_min_terminal_rows(),
            sdl_min_terminal_mode_name(config.min_terminal_mode));
        *window_height = min_height;
    }
}

static void sdl_format_layout_recovery_message(const char* reason,
    const sdl_layout_recovery_result* recovery, char* buf, size_t buflen)
{
    const char* prefix = "Layout recovery";

    if (!buf || !buflen)
        return;

    buf[0] = '\0';

    if (!recovery)
        return;

    if (reason && reason[0]) {
        if (streq(reason, "startup"))
            prefix = "At startup";
        else if (streq(reason, "window resize"))
            prefix = "Window resize";
        else if (streq(reason, "display scale change"))
            prefix = "Display scale change";
        else if (streq(reason, "fullscreen change"))
            prefix = "Fullscreen change";
        else if (streq(reason, "settings change"))
            prefix = "Settings change";
        else
            prefix = reason;
    }

    if (recovery->mode_changed && recovery->scale_changed) {
        strnfmt(buf, buflen,
            "%s: switched to %s terminal layout and reduced main view scale from %d to %d to keep the window usable.",
            prefix, sdl_min_terminal_mode_name(recovery->new_mode),
            recovery->old_scale, recovery->new_scale);
    } else if (recovery->mode_changed) {
        strnfmt(buf, buflen,
            "%s: switched from %s to %s terminal layout to fit the current window.",
            prefix, sdl_min_terminal_mode_name(recovery->old_mode),
            sdl_min_terminal_mode_name(recovery->new_mode));
    } else if (recovery->scale_changed) {
        strnfmt(buf, buflen,
            "%s: reduced main view scale from %d to %d to keep the %s terminal visible.",
            prefix, recovery->old_scale, recovery->new_scale,
            sdl_min_terminal_mode_name(recovery->new_mode));
    }
}

static void sdl_append_issue_line(char* buf, size_t buflen, const char* line)
{
    if (!buf || !buflen || !line || !line[0])
        return;

    if (buf[0])
        SDL_strlcat(buf, "\n", buflen);
    SDL_strlcat(buf, line, buflen);
}

static bool sdl_recover_layout_for_current_window(const char* reason,
    bool notify_user, sdl_layout_recovery_result* recovery)
{
    SDL_Rect screen;
    sdl_layout_recovery_result local = {
        .mode_changed = false,
        .scale_changed = false,
        .old_mode = config.min_terminal_mode,
        .new_mode = config.min_terminal_mode,
        .old_scale = config.main_view_scale,
        .new_scale = config.main_view_scale,
    };
    char notice[256];

    if (!g_state.window)
        return false;

    sdl_refresh_safe_area();
    screen = sdl_get_layout_screen_rect();
    if (!sdl_rect_has_area(&screen))
        return false;

    if (config.min_terminal_mode == SDL_MIN_TERMINAL_NORMAL
        && !sdl_mode_scale_fits_window(&screen, SDL_MIN_TERMINAL_NORMAL,
            config.main_view_scale, NULL, NULL))
    {
        log_info("%s: normal minimum terminal no longer fits; activating compact layout",
            reason ? reason : "layout change");
        set_sdl_min_terminal_mode(SDL_MIN_TERMINAL_COMPACT);
        local.mode_changed = true;
        local.new_mode = config.min_terminal_mode;
        local.new_scale = config.main_view_scale;
    }

    if (!sdl_mode_scale_fits_window(&screen, config.min_terminal_mode,
            config.main_view_scale, NULL, NULL))
    {
        int max_scale = sdl_max_scale_for_window_mode(config.min_terminal_mode);
        int min_scale = sdl_main_view_scale_floor();

        if (max_scale < min_scale)
            max_scale = min_scale;

        if (config.main_view_scale > max_scale) {
            log_info("%s: clamping main_view_scale from %d to %d for %s minimum terminal",
                reason ? reason : "layout change",
                config.main_view_scale, max_scale,
                sdl_min_terminal_mode_name(config.min_terminal_mode));
            config.main_view_scale = max_scale;
            local.scale_changed = true;
            local.new_scale = config.main_view_scale;
        }
    }

    if (recovery)
        *recovery = local;

    if (!(local.mode_changed || local.scale_changed))
        return false;

    if (notify_user && Term) {
        sdl_format_layout_recovery_message(reason, &local, notice,
            sizeof(notice));
        if (notice[0])
            msg_print(notice);
    }

    return true;
}

static bool sdl_prompt_reset_sdl_defaults(const char* issue_summary,
    int screen_width, int screen_height)
{
    enum {
        SDL_STARTUP_KEEP_RECOVERED = 0,
        SDL_STARTUP_LOAD_DEFAULTS = 1,
    };
    SDL_MessageBoxButtonData buttons[] = {
        { SDL_MESSAGEBOX_BUTTON_ESCAPEKEY_DEFAULT,
            SDL_STARTUP_KEEP_RECOVERED, "Keep Recovered Settings" },
        { SDL_MESSAGEBOX_BUTTON_RETURNKEY_DEFAULT,
            SDL_STARTUP_LOAD_DEFAULTS, "Load Defaults" },
    };
    char message[SDL_STARTUP_ISSUE_MAX + 256];
    SDL_MessageBoxData messagebox = {
        .flags = SDL_MESSAGEBOX_WARNING | SDL_MESSAGEBOX_BUTTONS_LEFT_TO_RIGHT,
        .window = g_state.window,
        .title = "SDL Config Recovery",
        .message = message,
        .numbuttons = (int)(sizeof(buttons) / sizeof(buttons[0])),
        .buttons = buttons,
        .colorScheme = NULL,
    };
    int button_id = SDL_STARTUP_KEEP_RECOVERED;

    if (!issue_summary || !issue_summary[0])
        return false;

    strnfmt(message, sizeof(message),
        "Sil-more adjusted your SDL settings so the game can start:\n\n%s\n\nLoad default SDL settings now? You can keep the recovered settings and change them later from SDL Pane Settings.",
        issue_summary);

    if (!SDL_ShowMessageBox(&messagebox, &button_id)) {
        log_warn("SDL_ShowMessageBox failed during startup recovery prompt: %s",
            SDL_GetError());
        return false;
    }

    if (button_id != SDL_STARTUP_LOAD_DEFAULTS)
        return false;

    sdl_reset_config_to_resolution_defaults(screen_width, screen_height);
    sdl_ensure_default_pane_profiles_present(false);
    sdl_apply_stored_pane_profile(config.min_terminal_mode);
    sdl_ensure_touch_pane_config_present();
    sdl_touch_pane_ensure_main_panel_confirm();
    sdl_config_save(config_file_path, &config, g_pane_profiles,
        SDL_PANE_PROFILE_COUNT);
    log_info("Startup recovery: reset SDL config to defaults at %s",
        config_file_path);
    return true;
}

#if SIL_SDL_DESKTOP_HANDHELD_BUILD
static bool sdl_resolution_matches_pair(int width, int height, int native_w,
    int native_h)
{
    return ((width == native_w && height == native_h)
        || (width == native_h && height == native_w));
}

static bool sdl_is_desktop_handheld_resolution(int width, int height)
{
    /* Native panel sizes for current Windows/Linux handhelds, plus common
     * handheld performance-mode targets. Check both orientations. */
    return sdl_resolution_matches_pair(width, height, 1280, 720)
        || sdl_resolution_matches_pair(width, height, 1280, 800)
        || sdl_resolution_matches_pair(width, height, 1920, 1080)
        || sdl_resolution_matches_pair(width, height, 1920, 1200)
        || sdl_resolution_matches_pair(width, height, 2560, 1600);
}

static sdl_startup_device_class sdl_prompt_desktop_startup_input_device(
    int screen_width, int screen_height)
{
    enum {
        SDL_STARTUP_INPUT_MOUSE_KEYBOARD = 0,
        SDL_STARTUP_INPUT_CONTROLLER = 1,
    };
    bool handheld_resolution =
        sdl_is_desktop_handheld_resolution(screen_width, screen_height);
    SDL_MessageBoxButtonData buttons[2];
    SDL_MessageBoxData messagebox = {
        .flags = SDL_MESSAGEBOX_INFORMATION
            | SDL_MESSAGEBOX_BUTTONS_LEFT_TO_RIGHT,
        .window = g_state.window,
        .title = "Choose Input",
        .message = "A controller is connected.\n\nUse controller input or mouse + keyboard input?\n\nController is recommended for handhelds. Mouse + keyboard is recommended for everything else.",
        .numbuttons = 2,
        .buttons = buttons,
        .colorScheme = NULL,
    };
    int button_id = handheld_resolution
        ? SDL_STARTUP_INPUT_CONTROLLER
        : SDL_STARTUP_INPUT_MOUSE_KEYBOARD;

    buttons[0] = (SDL_MessageBoxButtonData){
        handheld_resolution ? SDL_MESSAGEBOX_BUTTON_RETURNKEY_DEFAULT
                            : 0,
        SDL_STARTUP_INPUT_CONTROLLER,
        "Controller",
    };
    buttons[1] = (SDL_MessageBoxButtonData){
        handheld_resolution ? SDL_MESSAGEBOX_BUTTON_ESCAPEKEY_DEFAULT
                            : (SDL_MESSAGEBOX_BUTTON_RETURNKEY_DEFAULT
                                | SDL_MESSAGEBOX_BUTTON_ESCAPEKEY_DEFAULT),
        SDL_STARTUP_INPUT_MOUSE_KEYBOARD,
        "Mouse + Keyboard",
    };

    if (!SDL_ShowMessageBox(&messagebox, &button_id)) {
        log_warn("SDL_ShowMessageBox failed during input selection: %s",
            SDL_GetError());
        return handheld_resolution
            ? SDL_STARTUP_DEVICE_DESKTOP_CONTROLLER
            : SDL_STARTUP_DEVICE_DESKTOP;
    }

    if (button_id == SDL_STARTUP_INPUT_CONTROLLER)
        return SDL_STARTUP_DEVICE_DESKTOP_CONTROLLER;

    return SDL_STARTUP_DEVICE_DESKTOP;
}
#endif

static bool sdl_touch_pane_binding_is_direction(int binding)
{
    switch (binding) {
    case '1':
    case '2':
    case '3':
    case '4':
    case '6':
    case '7':
    case '8':
    case '9':
        return true;
    default:
        return false;
    }
}

static bool sdl_touch_pane_slot_uses_long_press(int slot, int binding)
{
    return (slot == 0)
        || sdl_touch_pane_binding_is_direction(binding)
        || (binding == 'z')
        || sdl_touch_pane_confirm_binding(binding);
}

static bool sdl_touch_pane_confirm_binding(int binding)
{
    return (binding == INPUT_BIND_CONFIRM || binding == ' ' || binding == '\r');
}

static bool sdl_touch_pane_main_panel_has_confirm_excluding(int skip_index)
{
    for (int i = 0; i < SDL_TOUCH_PANE_VISIBLE_BUTTON_COUNT; i++) {
        int slot = sdl_touch_pane_visible_slot_at(i);

        if (slot < 0 || slot == skip_index)
            continue;

        if (sdl_touch_pane_confirm_binding(config.touch_pane_bindings[slot]))
            return true;
    }

    return false;
}

static void sdl_touch_pane_ensure_main_panel_confirm(void)
{
    if (sdl_touch_pane_main_panel_has_confirm_excluding(-1))
        return;

    if (config.touch_pane_bindings[SDL_TOUCH_PANE_CENTER_SLOT] != INPUT_BIND_CONFIRM)
        log_warn("Touch pane main panel had no Confirm (pick) binding; restoring center button");

    config.touch_pane_bindings[SDL_TOUCH_PANE_CENTER_SLOT] = INPUT_BIND_CONFIRM;
    clear_sdl_touch_pane_button_label_for_panel(SDL_TOUCH_PANE_PANEL_MAIN,
        SDL_TOUCH_PANE_CENTER_SLOT);
}

static void sdl_touch_pane_begin_reset_confirm(void)
{
    g_touch_pane_reset_confirm_active = true;
    g_state.need_present = true;
}

static void sdl_touch_pane_finish_reset_confirm(bool confirmed)
{
    g_touch_pane_reset_confirm_active = false;

    if (confirmed) {
        sdl_touch_pane_reset_bindings_to_default();
        msg_print("Touch controls reset to defaults.");
    }

    g_state.need_present = true;
}

static void sdl_touch_pane_handle_reset_prompt_pointer(float x, float y)
{
    int slot = -1;
    int panel;
    int binding;

    if (!sdl_touch_pane_point_to_slot(x, y, &slot))
        return;
    if (slot < 0)
        return;

    panel = sdl_touch_pane_active_panel();
    binding = sdl_touch_pane_effective_binding_for_panel(panel, slot);

    if (slot == 0 || binding == ESCAPE) {
        sdl_touch_pane_finish_reset_confirm(false);
    } else if (sdl_touch_pane_confirm_binding(binding)) {
        sdl_touch_pane_finish_reset_confirm(true);
    }
}

static bool sdl_touch_pane_compute_layout(const SDL_Rect* pane_rect, SDL_FRect* slot_rects)
{
    float gap;
    float usable_w;
    float usable_h;
    float button_from_w;
    float button_from_h;
    float button_size;
    float grid_w;
    float grid_h;
    float start_x;
    float start_y;

    if (!pane_rect || !slot_rects || pane_rect->w <= 0 || pane_rect->h <= 0)
        return false;

    gap = (float)((pane_rect->w < pane_rect->h) ? pane_rect->w : pane_rect->h) / 40.0f;
    if (gap < 4.0f)
        gap = 4.0f;
    if (gap > 12.0f)
        gap = 12.0f;

    usable_w = (float)pane_rect->w - gap * 2.0f;
    usable_h = (float)pane_rect->h - gap * 2.0f;
    button_from_w = (usable_w - gap * (SDL_TOUCH_PANE_BUTTON_COLS - 1)) / SDL_TOUCH_PANE_BUTTON_COLS;
    button_from_h = (usable_h - gap * (SDL_TOUCH_PANE_VISIBLE_BUTTON_ROWS - 1)) / SDL_TOUCH_PANE_VISIBLE_BUTTON_ROWS;
    button_size = (button_from_w < button_from_h) ? button_from_w : button_from_h;
    if (button_size < 12.0f)
        return false;

    grid_w = button_size * SDL_TOUCH_PANE_BUTTON_COLS + gap * (SDL_TOUCH_PANE_BUTTON_COLS - 1);
    grid_h = button_size * SDL_TOUCH_PANE_VISIBLE_BUTTON_ROWS + gap * (SDL_TOUCH_PANE_VISIBLE_BUTTON_ROWS - 1);
    start_x = (float)pane_rect->x + ((float)pane_rect->w - grid_w) * 0.5f;
    start_y = sdl_mobile_prefer_safe_edge_alignment()
        ? ((float)pane_rect->y + gap)
        : ((float)pane_rect->y + ((float)pane_rect->h - grid_h) * 0.5f);

    for (int i = 0; i < SDL_TOUCH_PANE_BUTTON_COUNT; i++)
        slot_rects[i] = (SDL_FRect){ 0 };

    for (int i = 0; i < SDL_TOUCH_PANE_VISIBLE_BUTTON_COUNT; i++) {
        int slot = sdl_touch_pane_visible_slot_at(i);
        int row = i / SDL_TOUCH_PANE_BUTTON_COLS;
        int col = i % SDL_TOUCH_PANE_BUTTON_COLS;

        if (slot < 0)
            continue;

        slot_rects[slot] = (SDL_FRect){
            .x = start_x + col * (button_size + gap),
            .y = start_y + row * (button_size + gap),
            .w = button_size,
            .h = button_size,
        };
    }

    return true;
}

static bool sdl_touch_pane_current_rect(SDL_Rect* out_rect)
{
    SDL_Rect panes[PANE_MAX];
    const SDL_Rect* pane;
    bool show_supporting_panes = sdl_should_show_supporting_panes();
    bool proto_touch = sdl_touch_pane_proto_mode_active();

    if (!out_rect)
        return false;
    if (!proto_touch && !sdl_touch_pane_is_config_enabled())
        return false;
    if (!proto_touch && sdl_touch_pane_hidden_mode_active())
        return false;
    if (!proto_touch && !sdl_touch_pane_mobile_layout_open())
        return false;

    if (show_supporting_panes || sdl_layout_matches_supporting_pane_visibility()) {
        pane = &g_pane_rects[PANE_TOUCH];
    } else {
        sdl_compute_display_panes(panes);
        pane = &panes[PANE_TOUCH];
    }

    if (pane->w <= 0 || pane->h <= 0)
        return false;

    *out_rect = *pane;
    return true;
}

static bool sdl_side_map_pane_current_rect(SDL_Rect* out_rect)
{
    const SDL_Rect* pane;

    if (!sdl_should_show_supporting_panes())
        return false;
    if (!sdl_layout_matches_supporting_pane_visibility())
        return false;

    pane = &g_pane_rects[PANE_MAP];
    if (pane->w <= 0 || pane->h <= 0)
        return false;

    if (out_rect)
        *out_rect = *pane;
    return true;
}

static const struct pane_config* sdl_status_pane_config(void)
{
    for (int i = 0; i < pane_config_count; i++) {
        if (pane_config[i].pane == PANE_STATUS)
            return &pane_config[i];
    }

    return NULL;
}

static const struct pane_config* sdl_depth_pane_config(void)
{
    for (int i = 0; i < pane_config_count; i++) {
        if (pane_config[i].pane == PANE_DEPTH)
            return &pane_config[i];
    }

    return NULL;
}

static const struct pane_config* sdl_main_menu_pane_config(void)
{
    for (int i = 0; i < pane_config_count; i++) {
        if (pane_config[i].pane == PANE_MAIN_MENU)
            return &pane_config[i];
    }

    return NULL;
}

static float sdl_overlay_panel_x(const SDL_Rect* anchor,
    enum pane_placement where, int panel_w)
{
    switch (where) {
    case PLACE_TOP_RIGHT:
    case PLACE_RIGHT_CENTER:
    case PLACE_BOTTOM_RIGHT:
        return (float)(anchor->x + anchor->w - panel_w);
    case PLACE_TOP_CENTER:
    case PLACE_BOTTOM_CENTER:
        return (float)anchor->x + ((float)anchor->w - (float)panel_w) * 0.5f;
    default:
        return (float)anchor->x;
    }
}

static float sdl_overlay_panel_y(const SDL_Rect* anchor,
    enum pane_placement where, int panel_h)
{
    switch (where) {
    case PLACE_BOTTOM_LEFT:
    case PLACE_BOTTOM_CENTER:
    case PLACE_BOTTOM_RIGHT:
        return (float)(anchor->y + anchor->h - panel_h);
    case PLACE_LEFT_CENTER:
    case PLACE_RIGHT_CENTER:
        return (float)anchor->y + ((float)anchor->h - (float)panel_h) * 0.5f;
    default:
        return (float)anchor->y;
    }
}

static SDL_FRect sdl_overlay_panel_rect(const SDL_Rect* anchor,
    enum pane_placement where, int panel_w, int panel_h,
    const SDL_Rect* screen)
{
    float x = sdl_overlay_panel_x(anchor, where, panel_w);
    float y = sdl_overlay_panel_y(anchor, where, panel_h);

    if (screen) {
        float margin = (float)sdl_overlay_margin_px();
        float min_x = (float)screen->x + margin;
        float min_y = (float)screen->y + margin;
        float max_x = (float)(screen->x + screen->w - panel_w) - margin;
        float max_y = (float)(screen->y + screen->h - panel_h) - margin;

        if (max_x < min_x) {
            min_x = (float)screen->x;
            max_x = (float)(screen->x + screen->w - panel_w);
            if (max_x < min_x)
                max_x = min_x;
        }
        if (max_y < min_y) {
            min_y = (float)screen->y;
            max_y = (float)(screen->y + screen->h - panel_h);
            if (max_y < min_y)
                max_y = min_y;
        }

        if (x < min_x)
            x = min_x;
        if (y < min_y)
            y = min_y;
        if (x > max_x)
            x = max_x;
        if (y > max_y)
            y = max_y;
    }

    return (SDL_FRect){
        .x = x,
        .y = y,
        .w = (float)panel_w,
        .h = (float)panel_h,
    };
}

static bool sdl_status_pane_current_rect(SDL_Rect* out_rect,
    enum pane_placement* out_where)
{
    const struct pane_config* pc = sdl_status_pane_config();
    const SDL_Rect* pane;
    SDL_Rect fallback;

    if (!pc || !pc->enabled)
        return false;
    if (screen_saved_fullscreen_active())
        return false;
    if (!sdl_layout_matches_supporting_pane_visibility())
        return false;

    pane = &g_pane_rects[PANE_STATUS];
    if (pane->w <= 0 || pane->h <= 0) {
        fallback = g_pane_rects[PANE_MAIN];
        if (fallback.w <= 0 || fallback.h <= 0)
            fallback = sdl_get_layout_screen_rect();
        pane = &fallback;
    }
    if (pane->w <= 0 || pane->h <= 0)
        return false;

    if (out_rect)
        *out_rect = *pane;
    if (out_where)
        *out_where = pc->where;
    return true;
}

static float sdl_touch_pane_clampf(float value, float min_value, float max_value)
{
    if (value < min_value)
        return min_value;
    if (value > max_value)
        return max_value;
    return value;
}

static int sdl_touch_pane_story_text_width(TTF_Font* font, cptr text)
{
    int width = 0;

    if (!font || !text || !text[0])
        return 0;

    TTF_MeasureString(font, text, strlen(text), 0, &width, NULL);
    return width;
}

static SDL_Color sdl_status_pane_color(byte attr)
{
    SDL_Color color = g_state.palette[attr];

    color.a = 255;
    return color;
}

static void sdl_status_pane_format_turns(char* buf, size_t buflen, int turns)
{
    if (!buf || buflen == 0)
        return;

    if (turns <= 0) {
        buf[0] = '\0';
        return;
    }

    strnfmt(buf, buflen, "%d", turns);
}

static void sdl_status_pane_add(status_pane_entry* entries, int max_entries,
    int* count, cptr label, cptr detail, byte attr)
{
    status_pane_entry* entry;

    if (!entries || !count || *count < 0 || *count >= max_entries)
        return;
    if (!label || !label[0])
        return;

    entry = &entries[*count];
    SDL_strlcpy(entry->label, label, sizeof(entry->label));
    SDL_strlcpy(entry->detail, detail ? detail : "", sizeof(entry->detail));
    entry->attr = attr;
    (*count)++;
}

static void sdl_status_pane_add_timed(status_pane_entry* entries,
    int max_entries, int* count, cptr label, int turns, byte attr)
{
    char detail[32];

    sdl_status_pane_format_turns(detail, sizeof(detail), turns);
    sdl_status_pane_add(entries, max_entries, count, label, detail, attr);
}

static bool sdl_status_pane_song_name(byte song, char* out, size_t out_sz)
{
    int ability;
    cptr name;
    cptr label;

    if (!out || out_sz == 0)
        return false;
    out[0] = '\0';

    if (song == SNG_NOTHING || !b_info || !b_name)
        return false;

    ability = ability_index(S_SNG, song);
    if (ability < 0)
        return false;

    name = b_name + b_info[ability].name;
    if (!name || !name[0])
        return false;

    label = (strncmp(name, "Song of ", 8) == 0) ? name + 8 : name;
    SDL_strlcpy(out, label, out_sz);
    return out[0] != '\0';
}

static bool sdl_status_pane_current_song_detail(char* out, size_t out_sz)
{
    char song1[32] = "";
    char song2[32] = "";

    if (!out || out_sz == 0)
        return false;
    out[0] = '\0';

    if (!p_ptr)
        return false;
    if (p_ptr->song1 == SNG_NOTHING && p_ptr->song2 == SNG_NOTHING)
        return false;

    (void)sdl_status_pane_song_name(p_ptr->song1, song1, sizeof(song1));
    (void)sdl_status_pane_song_name(p_ptr->song2, song2, sizeof(song2));

    if (song1[0] && song2[0])
        strnfmt(out, out_sz, "%s+%s", song1, song2);
    else if (song1[0])
        SDL_strlcpy(out, song1, out_sz);
    else if (song2[0])
        SDL_strlcpy(out, song2, out_sz);
    else
        SDL_strlcpy(out, "active", out_sz);

    return out[0] != '\0';
}

static int sdl_status_pane_collect(status_pane_entry* entries, int max_entries)
{
    int count = 0;
    char detail[64];

    if (!entries || max_entries <= 0 || !p_ptr || !character_generated
        || character_icky)
    {
        return 0;
    }

    if (p_ptr->running > 0)
        sdl_status_pane_add_timed(entries, max_entries, &count, "Running",
            p_ptr->running, TERM_L_BLUE);
    if (p_ptr->stealth_mode)
        sdl_status_pane_add(entries, max_entries, &count, "Stealth",
            "", TERM_L_BLUE);
    if (p_ptr->focused)
        sdl_status_pane_add(entries, max_entries, &count, "Focused",
            "", TERM_L_BLUE);
    if (sdl_status_pane_current_song_detail(detail, sizeof(detail)))
        sdl_status_pane_add(entries, max_entries, &count, "Singing",
            detail, TERM_L_BLUE);
    if (p_ptr->song_contest_player_stacks > 0) {
        strnfmt(detail, sizeof(detail), "%d",
            p_ptr->song_contest_player_stacks);
        sdl_status_pane_add(entries, max_entries, &count, "Contest",
            detail, TERM_L_BLUE);
    }
    if (p_ptr->smithing > 0)
        sdl_status_pane_add_timed(entries, max_entries, &count, "Smithing",
            p_ptr->smithing, TERM_WHITE);
    if (p_ptr->fletching > 0)
        sdl_status_pane_add_timed(entries, max_entries, &count, "Fletching",
            p_ptr->fletching, TERM_WHITE);
    if (p_ptr->resting) {
        if (p_ptr->resting == -1)
            SDL_strlcpy(detail, "until healed", sizeof(detail));
        else if (p_ptr->resting == -2)
            SDL_strlcpy(detail, "until done", sizeof(detail));
        else
            sdl_status_pane_format_turns(detail, sizeof(detail),
                p_ptr->resting);
        sdl_status_pane_add(entries, max_entries, &count, "Resting",
            detail, TERM_WHITE);
    }
    if (p_ptr->command_rep > 0) {
        strnfmt(detail, sizeof(detail), "%d left", p_ptr->command_rep);
        sdl_status_pane_add(entries, max_entries, &count, "Repeat",
            detail, TERM_WHITE);
    }

    if (p_ptr->entranced > 0)
        sdl_status_pane_add_timed(entries, max_entries, &count, "Entranced",
            p_ptr->entranced, TERM_RED);
    if (p_ptr->afraid > 0)
        sdl_status_pane_add_timed(entries, max_entries, &count, "Afraid",
            p_ptr->afraid, TERM_ORANGE);
    if (p_ptr->confused > 0)
        sdl_status_pane_add_timed(entries, max_entries, &count, "Confused",
            p_ptr->confused, TERM_ORANGE);
    if (p_ptr->stun > 100)
        sdl_status_pane_add_timed(entries, max_entries, &count, "Knocked out",
            p_ptr->stun, TERM_RED);
    else if (p_ptr->stun > 50)
        sdl_status_pane_add_timed(entries, max_entries, &count, "Heavy stun",
            p_ptr->stun, TERM_ORANGE);
    else if (p_ptr->stun > 0)
        sdl_status_pane_add_timed(entries, max_entries, &count, "Stunned",
            p_ptr->stun, TERM_ORANGE);
    if (p_ptr->blind > 0)
        sdl_status_pane_add_timed(entries, max_entries, &count, "Blind",
            p_ptr->blind, TERM_ORANGE);
    if (p_ptr->image > 0)
        sdl_status_pane_add_timed(entries, max_entries, &count,
            "Hallucinating", p_ptr->image, TERM_VIOLET);
    if (p_ptr->poisoned > 0)
        sdl_status_pane_add_timed(entries, max_entries, &count, "Poisoned",
            p_ptr->poisoned, TERM_L_GREEN);
    if (p_ptr->cut > 100)
        sdl_status_pane_add_timed(entries, max_entries, &count,
            "Mortal wound", p_ptr->cut, TERM_RED);
    else if (p_ptr->cut > 0)
        sdl_status_pane_add_timed(entries, max_entries, &count, "Bleeding",
            p_ptr->cut, (p_ptr->cut > 20) ? TERM_RED : TERM_L_RED);
    if (p_ptr->darkened > 0)
        sdl_status_pane_add_timed(entries, max_entries, &count, "Darkened",
            p_ptr->darkened, TERM_SLATE);
    if (p_ptr->rage > 0)
        sdl_status_pane_add_timed(entries, max_entries, &count, "Rage",
            p_ptr->rage, TERM_RED);

    if (p_ptr->food < PY_FOOD_STARVE)
        sdl_status_pane_add(entries, max_entries, &count, "Starving",
            "", TERM_RED);
    else if (p_ptr->food < PY_FOOD_WEAK)
        sdl_status_pane_add(entries, max_entries, &count, "Weak",
            "", TERM_ORANGE);
    else if (p_ptr->food < PY_FOOD_ALERT)
        sdl_status_pane_add(entries, max_entries, &count, "Hungry",
            "", TERM_YELLOW);
    else if (p_ptr->food >= PY_FOOD_FULL)
        sdl_status_pane_add(entries, max_entries, &count, "Full",
            "", TERM_L_GREEN);

    if (p_ptr->fast > 0)
        sdl_status_pane_add_timed(entries, max_entries, &count, "Fast",
            p_ptr->fast, TERM_L_GREEN);
    if (p_ptr->slow > 0)
        sdl_status_pane_add_timed(entries, max_entries, &count, "Slow",
            p_ptr->slow, TERM_ORANGE);
    if (!p_ptr->fast && !p_ptr->slow && p_ptr->pspeed > 2)
        sdl_status_pane_add(entries, max_entries, &count, "Fast",
            "", TERM_L_GREEN);
    else if (!p_ptr->fast && !p_ptr->slow && p_ptr->pspeed < 2)
        sdl_status_pane_add(entries, max_entries, &count, "Slow",
            "", TERM_ORANGE);
    if (p_ptr->tmp_str > 0)
        sdl_status_pane_add_timed(entries, max_entries, &count, "Strong",
            p_ptr->tmp_str, TERM_L_GREEN);
    if (p_ptr->tmp_dex > 0)
        sdl_status_pane_add_timed(entries, max_entries, &count, "Agile",
            p_ptr->tmp_dex, TERM_L_GREEN);
    if (p_ptr->tmp_con > 0)
        sdl_status_pane_add_timed(entries, max_entries, &count, "Resilient",
            p_ptr->tmp_con, TERM_L_GREEN);
    if (p_ptr->tmp_gra > 0)
        sdl_status_pane_add_timed(entries, max_entries, &count, "Grace",
            p_ptr->tmp_gra, TERM_L_GREEN);
    if (p_ptr->tmp_per > 0)
        sdl_status_pane_add_timed(entries, max_entries, &count, "Perceptive",
            p_ptr->tmp_per, TERM_L_GREEN);
    if (p_ptr->tim_invis > 0)
        sdl_status_pane_add_timed(entries, max_entries, &count,
            "See invisible", p_ptr->tim_invis, TERM_L_BLUE);
    if (p_ptr->oppose_fire > 0)
        sdl_status_pane_add_timed(entries, max_entries, &count,
            "Resist fire", p_ptr->oppose_fire, TERM_L_RED);
    if (p_ptr->oppose_cold > 0)
        sdl_status_pane_add_timed(entries, max_entries, &count,
            "Resist cold", p_ptr->oppose_cold, TERM_L_BLUE);
    if (p_ptr->oppose_pois > 0)
        sdl_status_pane_add_timed(entries, max_entries, &count,
            "Resist poison", p_ptr->oppose_pois, TERM_L_GREEN);
    if (p_ptr->song_challenge_effect > 0)
        sdl_status_pane_add_timed(entries, max_entries, &count,
            "Challenge echo", p_ptr->song_challenge_effect, TERM_ORANGE);
    if (p_ptr->song_elbereth_effect > 0)
        sdl_status_pane_add_timed(entries, max_entries, &count,
            "Elbereth echo", p_ptr->song_elbereth_effect, TERM_ORANGE);
    if (p_ptr->song_lockout_timer > 0)
        sdl_status_pane_add_timed(entries, max_entries, &count,
            "Song lockout", p_ptr->song_lockout_timer, TERM_SLATE);

    if (p_ptr->climbing)
        sdl_status_pane_add(entries, max_entries, &count, "Climbing",
            "", TERM_WHITE);
    if (p_ptr->leaping)
        sdl_status_pane_add(entries, max_entries, &count, "Leaping",
            "", TERM_WHITE);
    if (p_ptr->knocked_back)
        sdl_status_pane_add(entries, max_entries, &count, "Knocked back",
            "", TERM_ORANGE);
    if (p_ptr->skip_next_turn)
        sdl_status_pane_add(entries, max_entries, &count, "Skip turn",
            "", TERM_ORANGE);
    if (p_ptr->was_entranced)
        sdl_status_pane_add(entries, max_entries, &count, "Waking",
            "", TERM_ORANGE);
    if (p_ptr->vengeance > 0) {
        strnfmt(detail, sizeof(detail), "%d", p_ptr->vengeance);
        sdl_status_pane_add(entries, max_entries, &count, "Vengeance",
            detail, TERM_L_RED);
    }
    if (p_ptr->truce)
        sdl_status_pane_add(entries, max_entries, &count, "Truce",
            "", TERM_L_BLUE);
    if (p_ptr->on_the_run)
        sdl_status_pane_add(entries, max_entries, &count, "On the run",
            "", TERM_L_RED);
    if (p_ptr->cursed)
        sdl_status_pane_add(entries, max_entries, &count, "Cursed",
            "", TERM_ORANGE);

    if (in_bounds(p_ptr->py, p_ptr->px)) {
        if (cave_pit_bold(p_ptr->py, p_ptr->px) && !p_ptr->leaping)
            sdl_status_pane_add(entries, max_entries, &count, "In pit",
                "", TERM_ORANGE);
        else if (cave_feat[p_ptr->py][p_ptr->px] == FEAT_TRAP_WEB)
            sdl_status_pane_add(entries, max_entries, &count, "In web",
                "", TERM_ORANGE);
        else if (cave_feat[p_ptr->py][p_ptr->px] == FEAT_SUNLIGHT)
            sdl_status_pane_add(entries, max_entries, &count, "Sunlight",
                "", TERM_YELLOW);
    }

    return count;
}

static void sdl_status_pane_entry_line(const status_pane_entry* entry,
    char* out, size_t out_sz)
{
    if (!out || out_sz == 0)
        return;
    out[0] = '\0';

    if (!entry || !entry->label[0])
        return;

    if (entry->detail[0])
        strnfmt(out, out_sz, "%s %s", entry->label, entry->detail);
    else
        SDL_strlcpy(out, entry->label, out_sz);
}

static int sdl_status_pane_text_width(TTF_Font* font, cptr text)
{
    int width = sdl_touch_pane_story_text_width(font, text);

    if (width < 0)
        width = 0;
    return width;
}

static bool sdl_status_pane_entry_prefers_span(const status_pane_entry* entry)
{
    if (!entry || !entry->label[0])
        return false;

    if (strcmp(entry->label, "Singing") == 0)
        return true;

    return false;
}

static int sdl_status_pane_layout_entries(TTF_Font* font,
    const status_pane_entry* entries, int visible_count, int more_count,
    status_pane_layout_item* items, int max_items, int max_content_w,
    int max_rows, int item_pad_x, int column_gap_x, int min_item_w,
    int* out_content_w, int* out_row_count)
{
    int item_count = 0;
    int max_column_w;
    int max_normal_w = 0;
    int max_span_w = 0;
    int normal_count = 0;
    int normal_columns;
    int content_w;
    int column_w;
    int row = 0;
    int col = 0;

    if (out_content_w)
        *out_content_w = 0;
    if (out_row_count)
        *out_row_count = 0;
    if (!font || !items || max_items <= 0 || max_content_w <= 0
        || max_rows <= 0)
    {
        return -1;
    }

    if (column_gap_x < 0)
        column_gap_x = 0;
    if (max_content_w <= column_gap_x)
        column_gap_x = 0;

    max_column_w = (max_content_w - column_gap_x) / SDL_STATUS_PANE_COLUMNS;
    if (max_column_w < 1)
        max_column_w = max_content_w;

    for (int i = 0; i < visible_count; i++) {
        status_pane_layout_item item = { 0 };
        int line_w;

        item.attr = entries[i].attr;
        sdl_status_pane_entry_line(&entries[i], item.line,
            sizeof(item.line));
        line_w = sdl_status_pane_text_width(font, item.line) + item_pad_x * 2;
        if (line_w < min_item_w)
            line_w = min_item_w;
        if (line_w > max_content_w)
            line_w = max_content_w;

        item.w = line_w;
        item.span = sdl_status_pane_entry_prefers_span(&entries[i])
            || line_w > max_column_w;
        if (item.span)
            max_span_w = MAX(max_span_w, line_w);
        else {
            max_normal_w = MAX(max_normal_w, line_w);
            normal_count++;
        }
        items[item_count++] = item;
        if (item_count >= max_items)
            break;
    }

    if (more_count > 0 && item_count < max_items) {
        status_pane_layout_item item = { 0 };
        int line_w;

        item.attr = TERM_SLATE;
        strnfmt(item.line, sizeof(item.line), "More +%d", more_count);
        line_w = sdl_status_pane_text_width(font, item.line) + item_pad_x * 2;
        if (line_w < min_item_w)
            line_w = min_item_w;
        if (line_w > max_content_w)
            line_w = max_content_w;

        item.w = line_w;
        item.span = line_w > max_column_w;
        if (item.span)
            max_span_w = MAX(max_span_w, line_w);
        else {
            max_normal_w = MAX(max_normal_w, line_w);
            normal_count++;
        }
        items[item_count++] = item;
    }

    if (item_count <= 0)
        return 0;

    normal_columns = (normal_count > 1) ? SDL_STATUS_PANE_COLUMNS : 1;
    if (max_normal_w > 0)
        content_w = max_normal_w * normal_columns
            + ((normal_columns > 1) ? column_gap_x : 0);
    else
        content_w = max_span_w;

    content_w = MAX(content_w, max_span_w);
    if (content_w < min_item_w)
        content_w = min_item_w;
    if (content_w > max_content_w)
        content_w = max_content_w;

    column_w = (normal_columns > 1)
        ? (content_w - column_gap_x) / normal_columns
        : content_w;
    if (column_w < 1)
        column_w = content_w;

    for (int i = 0; i < item_count; i++) {
        status_pane_layout_item* item = &items[i];

        if (item->span) {
            if (col != 0) {
                row++;
                col = 0;
            }
            item->row = row;
            item->x = 0;
            item->w = content_w;
            row++;
            col = 0;
        } else {
            item->row = row;
            item->x = col * (column_w + column_gap_x);
            item->w = column_w;
            col++;
            if (col >= normal_columns) {
                row++;
                col = 0;
            }
        }
    }

    if (col != 0)
        row++;

    if (row > max_rows)
        return -1;

    if (out_content_w)
        *out_content_w = content_w;
    if (out_row_count)
        *out_row_count = row;

    return item_count;
}

static void sdl_status_pane_draw_text(TTF_Font* font, cptr text,
    SDL_Color color, float x, float y, float max_w, float row_h,
    bool right_align)
{
    SDL_Surface* surface;
    SDL_Texture* texture;
    SDL_FRect dst;
    float scale = 1.0f;

    if (!font || !text || !text[0] || max_w <= 0.0f || row_h <= 0.0f)
        return;

    surface = TTF_RenderText_Blended(font, text, 0, color);
    if (!surface)
        return;

    texture = SDL_CreateTextureFromSurface(g_state.renderer, surface);
    if (!texture) {
        SDL_DestroySurface(surface);
        return;
    }

    if (surface->w > 0 && (float)surface->w > max_w)
        scale = max_w / (float)surface->w;

    dst.w = (float)surface->w * scale;
    dst.h = (float)surface->h * scale;
    dst.x = right_align ? x + max_w - dst.w : x;
    dst.y = y + (row_h - dst.h) * 0.5f;

    SDL_SetTextureBlendMode(texture, SDL_BLENDMODE_BLEND);
    SDL_RenderTexture(g_state.renderer, texture, NULL, &dst);

    SDL_DestroyTexture(texture);
    SDL_DestroySurface(surface);
}

static bool sdl_status_pane_layout(status_pane_layout* out)
{
    status_pane_entry entries[SDL_STATUS_PANE_MAX_ENTRIES];
    SDL_Rect anchor;
    SDL_Rect screen;
    enum pane_placement where;
    TTF_Font* font;
    int count;
    int font_px;
    int row_h;
    int pad_x;
    int pad_y;
    int item_pad_x;
    int gap_x;
    int min_item_w;
    int max_panel_w;
    int max_panel_h;
    int max_content_w;
    int max_rows;
    int visible_count;
    int more_count;
    int layout_count;
    int content_w = 0;
    int row_count = 0;
    int panel_w;
    int panel_h;

    if (!out)
        return false;
    *out = (status_pane_layout){ 0 };

    if (!sdl_status_pane_current_rect(&anchor, &where))
        return false;

    count = sdl_status_pane_collect(entries, SDL_STATUS_PANE_MAX_ENTRIES);
    if (count <= 0)
        return false;

    font_px = sdl_effective_pane_cell_height_for_type(PANE_STATUS);
    if (font_px < 8)
        font_px = 8;
    font = sdl_story_font_for_height(font_px);
    if (!font)
        return false;

    row_h = (int)((float)font_px * 1.35f + 0.5f);
    if (row_h < font_px + 2)
        row_h = font_px + 2;
    pad_x = (int)((float)font_px * 0.45f + 0.5f);
    pad_y = (int)((float)font_px * 0.32f + 0.5f);
    if (pad_x < 5)
        pad_x = 5;
    if (pad_y < 4)
        pad_y = 4;
    item_pad_x = pad_x / 2;
    if (item_pad_x < 4)
        item_pad_x = 4;
    gap_x = item_pad_x;
    min_item_w = font_px * 3;

    screen = sdl_get_layout_screen_rect();
    max_panel_w = screen.w - pad_x * 2;
    max_panel_h = screen.h - pad_y * 2;
    if (max_panel_w <= 0 || max_panel_h <= 0)
        return false;

    max_content_w = max_panel_w - pad_x * 2;
    if (max_content_w <= 0)
        return false;
    max_rows = (max_panel_h - pad_y * 2) / row_h;
    if (max_rows <= 0)
        return false;

    visible_count = count;
    for (;;) {
        more_count = count - visible_count;
        layout_count = sdl_status_pane_layout_entries(font, entries,
            visible_count, more_count, out->items, SDL_STATUS_PANE_MAX_ENTRIES,
            max_content_w, max_rows, item_pad_x, gap_x, min_item_w,
            &content_w, &row_count);

        if (layout_count >= 0)
            break;
        if (visible_count <= 0)
            return false;
        visible_count--;
    }

    if (layout_count <= 0)
        return false;

    panel_w = pad_x * 2 + content_w;
    if (panel_w > max_panel_w)
        panel_w = max_panel_w;

    panel_h = pad_y * 2 + row_count * row_h;
    if (panel_h > max_panel_h)
        panel_h = max_panel_h;

    out->panel = sdl_overlay_panel_rect(&anchor, where, panel_w,
        panel_h, &screen);
    out->layout_count = layout_count;
    out->font_px = font_px;
    out->row_h = row_h;
    out->pad_x = pad_x;
    out->pad_y = pad_y;
    out->item_pad_x = item_pad_x;

    return true;
}

static void sdl_status_pane_render(void)
{
    status_pane_layout layout;
    TTF_Font* font;

    if (!sdl_status_pane_layout(&layout))
        return;

    font = sdl_story_font_for_height(layout.font_px);
    if (!font)
        return;

    SDL_SetRenderDrawBlendMode(g_state.renderer, SDL_BLENDMODE_BLEND);
    SDL_SetRenderDrawColor(g_state.renderer, 5, 7, 9, 222);
    SDL_RenderFillRect(g_state.renderer, &layout.panel);

    {
        float text_x = layout.panel.x + (float)layout.pad_x;

        for (int i = 0; i < layout.layout_count; i++) {
            status_pane_layout_item* item = &layout.items[i];
            SDL_Color color;
            float item_x = text_x + (float)item->x;
            float item_text_x = item_x + (float)layout.item_pad_x;
            float item_text_w = (float)item->w
                - (float)(layout.item_pad_x * 2);
            float row_y = layout.panel.y + (float)layout.pad_y
                + (float)(item->row * layout.row_h);

            if (item_text_w <= 0.0f)
                continue;

            color = sdl_status_pane_color(item->attr);
            sdl_status_pane_draw_text(font, item->line, color,
                item_text_x, row_y, item_text_w, (float)layout.row_h,
                false);
        }
    }
}

static bool sdl_overlay_pane_anchor_rect(enum pane_type pane_type,
    SDL_Rect* out)
{
    const sdl_view* view = &g_views[PANE_MAIN];
    SDL_Rect anchor;
    SDL_Rect screen;

    if (!out)
        return false;
    *out = (SDL_Rect){ 0 };

    if (pane_type > PANE_MAIN && pane_type < PANE_MAX
        && sdl_rect_has_area(&g_pane_rects[pane_type]))
    {
        *out = g_pane_rects[pane_type];
        return true;
    }

    screen = sdl_get_layout_screen_rect();
    if (view->term_ready && view->canvas && view->cell_w > 0
        && view->cell_h > 0 && view->rect.w > 0 && view->rect.h > 0)
    {
        int visual_cols = sdl_main_view_visual_cols(view);
        int visual_rows = sdl_main_view_visual_rows(view);

        anchor = (SDL_Rect){
            .x = view->rect.x + view->margin_x,
            .y = view->rect.y + view->margin_y,
            .w = visual_cols * view->cell_w,
            .h = visual_rows * view->cell_h,
        };
    }
    else
    {
        anchor = (SDL_Rect){
            .x = screen.x,
            .y = screen.y,
            .w = screen.w,
            .h = screen.h,
        };
    }

    if (!sdl_rect_has_area(&anchor))
        return false;

    *out = anchor;
    return true;
}

static int sdl_main_menu_pane_font_px(void)
{
    int font_px = sdl_effective_pane_cell_height_for_type(PANE_MAIN_MENU);

    if (font_px < 8)
        font_px = 8;

    return font_px;
}

typedef struct main_menu_pane_layout {
    SDL_FRect panel;
    SDL_FRect rows[MAIN_MENU_MAX + 1];
    float pad_x;
    float row_h;
    float title_w;
    float shortcut_w;
    float shortcut_gap;
    int font_px;
    int first_choice;
    int visible_count;
} main_menu_pane_layout;

typedef enum main_menu_text_align {
    MAIN_MENU_TEXT_LEFT = 0,
    MAIN_MENU_TEXT_RIGHT,
    MAIN_MENU_TEXT_CENTER
} main_menu_text_align;

static bool sdl_main_menu_pane_context_visible(void)
{
    const struct pane_config* pc = sdl_main_menu_pane_config();
    SDL_Rect screen;

    if (!pc || !pc->enabled)
        return false;
    if (!character_generated || !character_dungeon || character_icky)
        return false;
    if (!p_ptr || screen_saved_fullscreen_active())
        return false;
    if (!death_spectator_active()
        && (!p_ptr->playing || p_ptr->leaving || p_ptr->is_dead))
    {
        return false;
    }

    screen = sdl_get_layout_screen_rect();
    if (screen.w <= 0 || screen.h <= 0)
        return false;

    return true;
}

static const char* sdl_main_menu_mono_font_path(void)
{
    return config.monospace_font[0] != '\0'
        ? config.monospace_font
        : "lib/xtra/font/VictorMono-Medium.ttf";
}

static TTF_Font* sdl_main_menu_mono_font_for_height(int font_px)
{
    const char* fallback = "lib/xtra/font/VictorMono-Medium.ttf";
    const char* font_path;
    TTF_Font* font;
    int cell_w;

    if (font_px <= 0)
        return NULL;

    cell_w = (font_px + 1) / 2;
    if (cell_w < 1)
        cell_w = 1;

    font_path = sdl_main_menu_mono_font_path();
    font = sdl_acquire_mono_font_cells(font_path, cell_w, font_px);
    if (!font && !streq(font_path, fallback))
        font = sdl_acquire_mono_font_cells(fallback, cell_w, font_px);

    return font;
}

static void sdl_main_menu_shortcut_display_label(int choice, char* buf,
    size_t buflen)
{
    char label[32];

    if (!buf || buflen == 0)
        return;

    buf[0] = '\0';
    main_menu_shortcut_label(choice, label, sizeof(label));
    if (!label[0])
        return;

    if (steamdeck_controls_active())
        strnfmt(buf, buflen, "[%s]", label);
    else
        strnfmt(buf, buflen, "(%s)", label);
}

static float sdl_main_menu_draw_text(TTF_Font* font, cptr text, float x,
    float y, float max_w, float row_h, SDL_Color color,
    main_menu_text_align align)
{
    SDL_Surface* surface;
    SDL_Texture* texture;
    SDL_FRect dst;
    float scale = 1.0f;
    float max_h;

    if (!font || !text || !text[0] || max_w <= 0.0f || row_h <= 0.0f)
        return 0.0f;

    surface = TTF_RenderText_Blended(font, text, 0, color);
    if (!surface)
        return 0.0f;

    texture = SDL_CreateTextureFromSurface(g_state.renderer, surface);
    if (!texture) {
        SDL_DestroySurface(surface);
        return 0.0f;
    }

    if (surface->w > 0 && (float)surface->w > max_w)
        scale = max_w / (float)surface->w;
    max_h = row_h * 0.86f;
    if (surface->h > 0 && (float)surface->h * scale > max_h)
        scale = max_h / (float)surface->h;
    if (scale > 1.0f)
        scale = 1.0f;

    dst.w = (float)surface->w * scale;
    dst.h = (float)surface->h * scale;
    if (align == MAIN_MENU_TEXT_RIGHT)
        dst.x = x + max_w - dst.w;
    else if (align == MAIN_MENU_TEXT_CENTER)
        dst.x = x + (max_w - dst.w) * 0.5f;
    else
        dst.x = x;
    dst.y = y + (row_h - dst.h) * 0.5f;

    SDL_SetTextureBlendMode(texture, SDL_BLENDMODE_BLEND);
    SDL_RenderTexture(g_state.renderer, texture, NULL, &dst);

    SDL_DestroyTexture(texture);
    SDL_DestroySurface(surface);
    return dst.w;
}

