static int sdl_touch_profile_normalized(int profile)
{
    if (profile >= SDL_TOUCH_PROFILE_TOUCH_PANE
        && profile < SDL_TOUCH_PROFILE_COUNT)
    {
        return profile;
    }

    return SDL_TOUCH_PROFILE_TOUCH_PANE;
}

