{
    get_sdl_touch_pane_button_label_for_panel(SDL_TOUCH_PANE_PANEL_MAIN, index, buf, buflen);
}

void set_sdl_touch_pane_button_label(int index, cptr label)
{
    set_sdl_touch_pane_button_label_for_panel(SDL_TOUCH_PANE_PANEL_MAIN, index, label);
}

void clear_sdl_touch_pane_button_label(int index)
{
    clear_sdl_touch_pane_button_label_for_panel(SDL_TOUCH_PANE_PANEL_MAIN, index);
}

void get_sdl_touch_pane_button_label_for_panel(int panel, int index, char* buf, size_t buflen)
{
    if (!sdl_touch_pane_panel_is_valid(panel)) {
        if (buf && buflen)
            buf[0] = '\0';
        return;
    }

    sdl_touch_pane_base_label_for_slot(panel, index, buf, buflen);
}

void set_sdl_touch_pane_button_label_for_panel(int panel, int index, cptr label)
{
    char (*labels)[SDL_TOUCH_PANE_LABEL_LEN];

    if (!sdl_touch_pane_panel_is_valid(panel))
        return;
    if (index < 0 || index >= SDL_TOUCH_PANE_BUTTON_COUNT)
        return;

    labels = (panel == SDL_TOUCH_PANE_PANEL_SECOND)
        ? config.touch_pane_second_labels
        : config.touch_pane_labels;

    if (!label || !label[0]) {
        labels[index][0] = '\x01';
        labels[index][1] = '\0';
        return;
    }

    SDL_strlcpy(labels[index], label, SDL_TOUCH_PANE_LABEL_LEN);
}

void clear_sdl_touch_pane_button_label_for_panel(int panel, int index)
{
    char (*labels)[SDL_TOUCH_PANE_LABEL_LEN];

    if (!sdl_touch_pane_panel_is_valid(panel))
        return;
    if (index < 0 || index >= SDL_TOUCH_PANE_BUTTON_COUNT)
        return;

    labels = (panel == SDL_TOUCH_PANE_PANEL_SECOND)
        ? config.touch_pane_second_labels
        : config.touch_pane_labels;
    labels[index][0] = '\0';
}

void get_sdl_touch_pane_panel_name(int panel, char* buf, size_t buflen)
{
    if (!buf || !buflen)
        return;

    buf[0] = '\0';

    if (!sdl_touch_pane_panel_is_valid(panel))
        return;

    sdl_touch_pane_load_default_bindings();
    if (config.touch_pane_panel_names[panel][0]) {
        SDL_strlcpy(buf, config.touch_pane_panel_names[panel], buflen);
    } else {
        SDL_strlcpy(buf, g_default_touch_pane_panel_names[panel], buflen);
    }
}

void set_sdl_touch_pane_panel_name(int panel, cptr name)
{
    if (!sdl_touch_pane_panel_is_valid(panel))
        return;

    if (!name || !name[0]) {
        config.touch_pane_panel_names[panel][0] = '\0';
        return;
    }

    SDL_strlcpy(config.touch_pane_panel_names[panel], name,
        sizeof(config.touch_pane_panel_names[panel]));
}

bool sdl_gamepad_capture_begin(bool allow_modifier_combo)
{
    g_gamepad_capture_ready = false;
    g_gamepad_capture_active = (g_gamepad_state.pad_count > 0);
    g_gamepad_capture_allow_modifier_combo = allow_modifier_combo;
    g_gamepad_capture_modifier = GAMEPAD_BIND_NONE;
    g_gamepad_capture_arm_time = SDL_GetTicksNS()
        + ((Uint64)GAMEPAD_CAPTURE_ARM_DELAY_MS * 1000000ULL);
    sdl_gamepad_clear_pending_shoulder();
    return g_gamepad_capture_active;
}

void sdl_gamepad_capture_cancel(void)
{
    g_gamepad_capture_active = false;
    g_gamepad_capture_ready = false;
    g_gamepad_capture_allow_modifier_combo = false;
    g_gamepad_capture_modifier = GAMEPAD_BIND_NONE;
    g_gamepad_capture_arm_time = 0;
    sdl_gamepad_clear_pending_shoulder();
}

bool sdl_gamepad_capture_poll(int* out_type, int* out_id, int* out_modifier)
{
    if (!g_gamepad_capture_ready)
        return false;

    if (out_type)
        *out_type = g_gamepad_capture_type;
    if (out_id)
        *out_id = g_gamepad_capture_id;
    if (out_modifier)
        *out_modifier = g_gamepad_capture_modifier;

    g_gamepad_capture_ready = false;
    g_gamepad_capture_active = false;
    g_gamepad_capture_allow_modifier_combo = false;
    g_gamepad_capture_modifier = GAMEPAD_BIND_NONE;
    g_gamepad_capture_arm_time = 0;
    sdl_gamepad_clear_pending_shoulder();
    return true;
}

/*
 * Calculate the maximum scale for the current window.
 * This keeps at least the configured minimum terminal size visible in the
 * current window.
 */
int get_sdl_max_scale(void)
{
    if (!g_state.window) {
        return 10; // fallback if window not initialized
    }
    
    SDL_Rect screen;
    int max_scale;

    sdl_refresh_safe_area();
    screen = sdl_get_layout_screen_rect();
    max_scale = sdl_max_scale_for_layout(&screen, config.min_terminal_mode);
    if (max_scale < sdl_main_view_scale_floor())
        max_scale = sdl_main_view_scale_floor();

    log_debug("get_sdl_max_scale: layout=(%d,%d %dx%d) min=%dx%d (%s) max_scale=%d",
              screen.x, screen.y, screen.w, screen.h,
              sdl_current_min_terminal_cols(), sdl_current_min_terminal_rows(),
              sdl_min_terminal_mode_name(config.min_terminal_mode), max_scale);
    
    return max_scale;
}

int get_sdl_max_main_view_zoom_scale(void)
{
    if (!g_state.window) {
        return 10;
    }

    SDL_Rect screen;
    int max_scale;
    int min_cols;
    int min_rows;

    sdl_refresh_safe_area();
    screen = sdl_get_layout_screen_rect();
    max_scale = sdl_max_main_view_zoom_scale_for_layout(&screen,
        config.min_terminal_mode);
    min_cols = sdl_main_view_terminal_cols_for_map_squares(
        SDL_MAIN_VIEW_ZOOM_MIN_MAP_SQUARES);
    min_rows = sdl_main_view_terminal_rows_for_map_squares(
        SDL_MAIN_VIEW_ZOOM_MIN_MAP_SQUARES);

    log_debug("get_sdl_max_main_view_zoom_scale: layout=(%d,%d %dx%d) min_visible_axis=%d map squares term_min=%dx%d max_scale=%d",
              screen.x, screen.y, screen.w, screen.h,
              SDL_MAIN_VIEW_ZOOM_MIN_MAP_SQUARES, min_cols, min_rows,
              max_scale);

    return max_scale;
}

static int get_sdl_min_main_view_zoom_scale(void)
{
    if (!g_state.window)
        return sdl_main_view_scale_floor();

    SDL_Rect screen;
    int min_scale;

    sdl_refresh_safe_area();
    screen = sdl_get_layout_screen_rect();
    min_scale = sdl_min_main_view_zoom_scale_for_layout(&screen,
        config.min_terminal_mode);

    log_debug("get_sdl_min_main_view_zoom_scale: layout=(%d,%d %dx%d) min_scale=%d",
              screen.x, screen.y, screen.w, screen.h, min_scale);

    return min_scale;
}

static void sdl_clamp_main_view_zoom_to_current_layout(void)
{
    int min_scale;
    int max_scale;
    int configured_scale;

    if (g_main_view_zoom_scale <= 0)
        return;

    min_scale = get_sdl_min_main_view_zoom_scale();
    max_scale = get_sdl_max_main_view_zoom_scale();
    if (min_scale < SDL_MAIN_VIEW_MIN_SCALE)
        min_scale = SDL_MAIN_VIEW_MIN_SCALE;
    if (max_scale < SDL_MAIN_VIEW_MIN_SCALE)
        max_scale = SDL_MAIN_VIEW_MIN_SCALE;
    if (max_scale < min_scale)
        max_scale = min_scale;

    if (g_main_view_zoom_scale < min_scale)
        g_main_view_zoom_scale = min_scale;
    if (g_main_view_zoom_scale > max_scale)
        g_main_view_zoom_scale = max_scale;

    configured_scale = sdl_configured_main_view_scale();
    if (g_main_view_zoom_scale == configured_scale)
        g_main_view_zoom_scale = 0;
}

void sdl_refresh_supporting_panes_layout(void)
{
    SDL_Rect screen;

    if (!g_state.window)
        return;
    if (sdl_layout_matches_supporting_pane_visibility())
        return;

    sdl_refresh_safe_area();
    screen = sdl_get_layout_screen_rect();
    /* The caller will either redraw the destination scene or restore a saved
     * main-term buffer immediately after the layout change. Redrawing the old
     * outgoing main contents here is what produces the visible "flash" frame. */
    g_skip_main_redraw_on_layout_refresh = true;
    g_suppress_layout_refresh_present = true;
    resize(&screen);
    g_suppress_layout_refresh_present = false;
    if (g_skip_main_redraw_on_layout_refresh)
        g_state.need_present = false;
    g_skip_main_redraw_on_layout_refresh = false;
}

void sdl_refresh_supporting_panes_layout_deferred(void)
{
    bool old_defer = g_defer_resize_handle_stuff;

    g_defer_resize_handle_stuff = true;
    sdl_refresh_supporting_panes_layout();
    g_defer_resize_handle_stuff = old_defer;
}

/*
 * Apply current SDL configuration by triggering a resize.
 * This makes changes to scale, font size, margin, etc. take effect immediately.
 */
static void sdl_apply_runtime_zoom(void)
{
    Uint64 start_ns = SDL_GetTicksNS();
    Uint64 story_ns;
    Uint64 resize_ns;
    int story_depth;
    bool global_story_active;
    bool global_story_grid;
    bool local_story_active = false;
    bool local_story_grid = false;
    int local_story_term_index = -1;

    if (!g_state.window) {
        log_warn("sdl_apply_runtime_zoom: no window, skipping");
        return;
    }

    story_depth = g_state.story_font_depth;
    global_story_active = (story_depth > 0);
    global_story_grid = g_state.story_font_grid;
    if (!global_story_active && Term
        && (Term->story_font_active || Term->story_font_grid))
    {
        size_t term_index = (size_t)(uintptr_t)Term->data;
        if (term_index < MAX_TERM_DATA) {
            local_story_term_index = (int)term_index;
            local_story_active = Term->story_font_active;
            local_story_grid = Term->story_font_grid;
        }
    }

    sdl_refresh_safe_area();
    sdl_clamp_main_view_zoom_to_current_layout();
    g_auto_aux_main_cell_h_override = config.main_view_scale * TILE_SIZE;
    story_ns = SDL_GetTicksNS();
    sdl_load_story_fonts();
    story_ns = SDL_GetTicksNS() - story_ns;
    resize_ns = SDL_GetTicksNS();
    sdl_resize_for_current_layout();
    resize_ns = SDL_GetTicksNS() - resize_ns;
    g_auto_aux_main_cell_h_override = 0;
    sdl_queue_main_view_scale_neighbors_prewarm("runtime zoom");

    if (global_story_active || global_story_grid) {
        g_state.story_font_depth = global_story_active ? story_depth : 0;
        sdl_apply_story_font_state(global_story_active);
        g_state.story_font_grid = global_story_grid;
        sdl_apply_story_grid_state(global_story_grid);
    } else if (local_story_term_index >= 0) {
        term* local_term = &g_views[local_story_term_index].t;
        local_term->story_font_active = local_story_active;
        local_term->story_font_grid = local_story_grid;
    }

    sdl_request_redraw();
    log_debug("sdl_apply_runtime_zoom completed in %llu ms (story=%llu ms resize=%llu ms configured=%d effective=%d)",
        (unsigned long long)((SDL_GetTicksNS() - start_ns) / 1000000ULL),
        (unsigned long long)(story_ns / 1000000ULL),
        (unsigned long long)(resize_ns / 1000000ULL),
        config.main_view_scale, sdl_current_main_view_scale());
}

static void sdl_apply_config_impl(bool request_redraw)
{
    Uint64 start_ns = SDL_GetTicksNS();
    Uint64 recovery_ns;
    Uint64 story_ns;
    Uint64 resize_ns;
    int story_depth;
    bool global_story_active;
    bool global_story_grid;
    bool local_story_active = false;
    bool local_story_grid = false;
    int local_story_term_index = -1;

    if (!g_state.window) {
        log_warn("sdl_apply_config: no window, skipping");
        return;
    }

    story_depth = g_state.story_font_depth;
    global_story_active = (story_depth > 0);
    global_story_grid = g_state.story_font_grid;
    if (!global_story_active && Term
        && (Term->story_font_active || Term->story_font_grid))
    {
        size_t term_index = (size_t)(uintptr_t)Term->data;
        if (term_index < MAX_TERM_DATA)
        {
            local_story_term_index = (int)term_index;
            local_story_active = Term->story_font_active;
            local_story_grid = Term->story_font_grid;
        }
    }

    recovery_ns = SDL_GetTicksNS();
    (void)sdl_recover_layout_for_current_window("settings change", true, NULL);
    recovery_ns = SDL_GetTicksNS() - recovery_ns;
    sdl_refresh_safe_area();
    sdl_clamp_main_view_zoom_to_current_layout();
    g_auto_aux_main_cell_h_override = config.main_view_scale * TILE_SIZE;
    story_ns = SDL_GetTicksNS();
    sdl_load_story_fonts();
    story_ns = SDL_GetTicksNS() - story_ns;
    resize_ns = SDL_GetTicksNS();
    sdl_resize_for_current_layout();
    resize_ns = SDL_GetTicksNS() - resize_ns;
    g_auto_aux_main_cell_h_override = 0;
    sdl_queue_main_view_scale_neighbors_prewarm("settings change");

    if (global_story_active || global_story_grid) {
        g_state.story_font_depth = global_story_active ? story_depth : 0;
        sdl_apply_story_font_state(global_story_active);
        g_state.story_font_grid = global_story_grid;
        sdl_apply_story_grid_state(global_story_grid);
    } else if (local_story_term_index >= 0) {
        term* local_term = &g_views[local_story_term_index].t;
        local_term->story_font_active = local_story_active;
        local_term->story_font_grid = local_story_grid;
    }
    
    if (request_redraw)
        sdl_request_redraw();
    else
        g_state.need_present = true;

    log_debug("sdl_apply_config completed in %llu ms (recover=%llu ms story=%llu ms resize=%llu ms redraw=%d)",
        (unsigned long long)((SDL_GetTicksNS() - start_ns) / 1000000ULL),
        (unsigned long long)(recovery_ns / 1000000ULL),
        (unsigned long long)(story_ns / 1000000ULL),
        (unsigned long long)(resize_ns / 1000000ULL),
        request_redraw ? 1 : 0);
}

void sdl_apply_config(void)
{
    sdl_apply_config_impl(true);
}

void sdl_apply_config_no_redraw(void)
{
    sdl_apply_config_impl(false);
}

int get_sdl_platform_max_main_view_scale(void)
{
    return sdl_platform_max_main_view_scale_for_mode(config.min_terminal_mode);
}

int get_sdl_terminal_menu_scale(void)
{
#if defined(SDL_PLATFORM_ANDROID) || defined(SDL_PLATFORM_IOS)
    int menu_mode = config.min_terminal_mode;
#else
    int menu_mode = SDL_MIN_TERMINAL_NORMAL;
#endif
    SDL_Rect screen;
    int max_scale = SDL_MAIN_VIEW_MIN_SCALE;
    bool supporting_panes_hidden = !sdl_should_show_supporting_panes();
    int platform_max = sdl_platform_max_main_view_scale_for_mode(menu_mode);
    int compact_platform_max =
        sdl_platform_max_main_view_scale_for_mode(SDL_MIN_TERMINAL_COMPACT);
    int min_scale = sdl_main_view_scale_floor_for_mode(menu_mode);
    int scale;

    if (supporting_panes_hidden) {
        sdl_refresh_safe_area();
        screen = sdl_get_layout_screen_rect();
        if (sdl_rect_has_area(&screen))
            max_scale = sdl_max_scale_for_rect_mode(&screen, menu_mode);
    } else {
        max_scale = sdl_max_scale_for_window_mode(menu_mode);
    }

    if (max_scale <= SDL_MAIN_VIEW_MIN_SCALE)
        scale = SDL_MAIN_VIEW_MIN_SCALE;
    else
    {
        /* Desktop/full-screen menus should keep one step below the normal
         * terminal maximum, even when gameplay is in compact mode. */
        scale = max_scale - 1;
        if (scale < min_scale)
            scale = min_scale;
    }

    log_debug("terminal menu scale: mode=%s hidden_supporting_panes=%d "
              "layout_max=%d platform_max=%d compact_platform_max=%d "
              "target=%d",
        sdl_min_terminal_mode_name(menu_mode),
        supporting_panes_hidden ? 1 : 0, max_scale, platform_max,
        compact_platform_max, scale);

    return scale;
}

void sdl_push_terminal_menu_scale(void)
{
    int old_scale = g_terminal_menu_scale_override;
    int target_scale = get_sdl_terminal_menu_scale();

    if (g_terminal_menu_scale_depth
        >= (int)N_ELEMENTS(g_terminal_menu_scale_stack))
    {
        log_warn("terminal menu scale stack is full");
        return;
    }

    g_terminal_menu_scale_stack[g_terminal_menu_scale_depth++] = old_scale;

    g_terminal_menu_scale_override = target_scale;
    if (old_scale != target_scale)
        sdl_apply_config_no_redraw();
}

void sdl_pop_terminal_menu_scale(void)
{
    int old_scale = g_terminal_menu_scale_override;
    int restored_scale = 0;

    if (g_terminal_menu_scale_depth > 0)
    {
        restored_scale =
            g_terminal_menu_scale_stack[--g_terminal_menu_scale_depth];
        g_terminal_menu_scale_stack[g_terminal_menu_scale_depth] = 0;
    }

    g_terminal_menu_scale_override = restored_scale;
    if (old_scale != restored_scale)
        sdl_apply_config_no_redraw();
}

bool sdl_description_overlay_present(const byte* attrs, const char* chars,
    const byte* tattrs, const char* tchars, const byte* story, int width,
    int height, int scroll, bool interactive, int* out_visible_rows,
    int* out_max_scroll)
{
    description_overlay_layout layout;

    if (out_visible_rows)
        *out_visible_rows = 1;
    if (out_max_scroll)
        *out_max_scroll = 0;

    if (!attrs || !chars || width <= 0 || height <= 0)
    {
        sdl_description_overlay_clear();
        return false;
    }

    g_description_overlay.active = true;
    g_description_overlay.interactive = interactive;
    g_description_overlay.attrs = attrs;
    g_description_overlay.chars = chars;
    g_description_overlay.tattrs = tattrs;
    g_description_overlay.tchars = tchars;
    g_description_overlay.story = story;
    g_description_overlay.width = width;
    g_description_overlay.height = height;
    g_description_overlay.scroll = scroll;

    if (!sdl_description_overlay_layout(&layout))
    {
        g_description_overlay = (description_overlay_state){ 0 };
        g_state.need_present = true;
        sdl_present_if_needed(&g_views[PANE_MAIN]);
        return false;
    }

    g_description_overlay.scroll = layout.scroll;
    if (out_visible_rows)
        *out_visible_rows = layout.visible_rows;
    if (out_max_scroll)
        *out_max_scroll = layout.max_scroll;

    g_state.need_present = true;
    sdl_present_if_needed(&g_views[PANE_MAIN]);
    return true;
}

void sdl_description_overlay_clear(void)
{
    if (!g_description_overlay.active)
        return;

    g_description_overlay = (description_overlay_state){ 0 };
    g_state.need_present = true;
    sdl_present_if_needed(&g_views[PANE_MAIN]);
}

void sdl_request_redraw(void)
{
    if (!g_state.window) {
        log_warn("sdl_request_redraw: no window, skipping");
        return;
    }

    g_state.need_present = true;
    Term_redraw();
}


static void sdl_apply_story_font_state(bool active)
{
    log_trace("Story font state apply: active=%s depth=%d term=%p",
              active ? "true" : "false", g_state.story_font_depth, (void*)Term);
    for (int i = 0; i < MAX_TERM_DATA; i++)
    {
        if (g_views[i].term_ready)
        {
            g_views[i].t.story_font_active = active;
        }
    }
    if (Term)
        Term->story_font_active = active;
}

static void sdl_apply_story_grid_state(bool grid)
{
    log_trace("Story grid state apply: grid=%s term=%p",
              grid ? "true" : "false", (void*)Term);
    for (int i = 0; i < MAX_TERM_DATA; i++)
    {
        if (g_views[i].term_ready)
        {
            g_views[i].t.story_font_grid = grid;
        }
    }
    if (Term)
        Term->story_font_grid = grid;
}

static void sdl_story_font_reset_state(void)
{
    g_state.story_font_depth = 0;
    sdl_apply_story_font_state(false);
    g_state.story_font_grid = false;
    sdl_apply_story_grid_state(false);
    if (Term)
        Term->story_chunk_active = false;
    log_trace("Story font state hard reset");
}

static void sdl_render_mono_text(sdl_view* d, int x, int y, int n, const char* s, SDL_Color col)
{
    if (!d || !d->font_atlas || n <= 0)
        return;

    SDL_SetTextureColorMod(d->font_atlas, col.r, col.g, col.b);
    SDL_SetTextureAlphaMod(d->font_atlas, 255);

    for (int i = 0; i < n; i++) {
        unsigned char ch = (unsigned char)s[i];
        int atlas_cell_w = (d->font_atlas_cell_w > 0)
            ? d->font_atlas_cell_w : d->cell_w;
        int atlas_cell_h = (d->font_atlas_cell_h > 0)
            ? d->font_atlas_cell_h : d->cell_h;
        SDL_FRect src = {
            (ch & 15) * atlas_cell_w,
            (ch >> 4) * atlas_cell_h,
            atlas_cell_w,
            atlas_cell_h,
        };
        SDL_FRect dst = {
            (x + i) * d->cell_w,
            y * d->cell_h,
            d->cell_w,
            d->cell_h
        };
        if (use_graphics == GRAPHICS_PSEUDO && solid_walls && (ch == '#' || ch == '%')) {
            SDL_SetRenderDrawColor(g_state.renderer, col.r, col.g, col.b, SDL_ALPHA_OPAQUE);
            SDL_RenderFillRect(g_state.renderer, &dst);
        }
        SDL_RenderTexture(g_state.renderer, d->font_atlas, &src, &dst);
    }
}

static void sdl_render_mono_utf8_glyph(TTF_Font* font, float cell_w,
    float cell_h, float origin_x, int x, int y, int cell_offset,
    int cell_span, const char* s, int len, SDL_Color col)
{
    char text_buf[8];
    SDL_Surface* text_surface;
    SDL_Texture* text_texture;

    if (!font || !s || len <= 0 || len >= (int)sizeof(text_buf)
        || cell_w <= 0.0f || cell_h <= 0.0f)
    {
        return;
    }

    if (cell_span < 1)
        cell_span = 1;

    memcpy(text_buf, s, (size_t)len);
    text_buf[len] = '\0';

    text_surface = TTF_RenderText_Blended(font, text_buf, 0, col);
    if (!text_surface)
        return;

    text_texture = SDL_CreateTextureFromSurface(g_state.renderer, text_surface);
    if (text_texture)
    {
        float surf_w_f = (float)text_surface->w;
        float surf_h_f = (float)text_surface->h;
        float scale = (surf_h_f > 0.0f) ? (cell_h / surf_h_f) : 1.0f;
        float render_w = surf_w_f * scale;
        float max_w = (float)cell_span * cell_w;
        SDL_FRect dst;

        if (render_w > max_w) {
            if (origin_x > 0.0f || g_left_panel_debug_dump_rows) {
                log_debug("left-panel utf8 glyph clamp: term_x=%d y=%d "
                    "offset=%d span=%d cell=%.1fx%.1f surf=%dx%d "
                    "scaled_w=%.1f max_w=%.1f first_byte=0x%02x",
                    x, y, cell_offset, cell_span, (double)cell_w,
                    (double)cell_h, text_surface->w, text_surface->h,
                    (double)render_w, (double)max_w,
                    (unsigned int)(unsigned char)s[0]);
            }
            render_w = max_w;
        }

        dst.x = origin_x + ((float)(x + cell_offset) * cell_w)
            + ((max_w - render_w) * 0.5f);
        dst.y = (float)y * cell_h;
        dst.w = render_w;
        dst.h = cell_h;

        SDL_SetTextureBlendMode(text_texture, SDL_BLENDMODE_BLEND);
        SDL_RenderTexture(g_state.renderer, text_texture, NULL, &dst);
        SDL_DestroyTexture(text_texture);
    }

    SDL_DestroySurface(text_surface);
}

static void sdl_render_mono_utf8_text_cells(SDL_Texture* atlas,
    int atlas_cell_w, int atlas_cell_h, TTF_Font* font, float cell_w,
    float cell_h, float origin_x, int x, int y, int n, const char* s,
    SDL_Color col)
{
    int byte_pos = 0;
    int cell_offset = 0;

    if (!s || n <= 0 || cell_w <= 0.0f || cell_h <= 0.0f)
        return;

    if (atlas)
    {
        SDL_SetTextureColorMod(atlas, col.r, col.g, col.b);
        SDL_SetTextureAlphaMod(atlas, 255);
    }

    while (byte_pos < n && s[byte_pos] && cell_offset < n)
    {
        unsigned char ch = (unsigned char)s[byte_pos];
        int remaining = n - byte_pos;
        int char_len = utf8_sequence_len_n(s + byte_pos, remaining);
        int char_width;

        if (char_len <= 0)
            break;

        if (ch < 0x80 || char_len == 1)
        {
            if (atlas)
            {
                SDL_FRect src = {
                    (float)((ch & 15) * atlas_cell_w),
                    (float)((ch >> 4) * atlas_cell_h),
                    (float)atlas_cell_w,
                    (float)atlas_cell_h,
                };
                SDL_FRect dst = {
                    origin_x + ((float)(x + cell_offset) * cell_w),
                    (float)y * cell_h,
                    cell_w,
                    cell_h,
                };

                if (use_graphics == GRAPHICS_PSEUDO && solid_walls
                    && (ch == '#' || ch == '%'))
                {
                    SDL_SetRenderDrawColor(g_state.renderer, col.r, col.g,
                        col.b, SDL_ALPHA_OPAQUE);
                    SDL_RenderFillRect(g_state.renderer, &dst);
                }

                SDL_RenderTexture(g_state.renderer, atlas, &src, &dst);
            }

            byte_pos++;
            cell_offset++;
            continue;
        }

        char_width = utf8_display_width_n(s + byte_pos, char_len);
        if (char_width <= 0)
        {
            int overlay_offset = (cell_offset > 0) ? (cell_offset - 1) : 0;
            sdl_render_mono_utf8_glyph(font, cell_w, cell_h, origin_x, x, y,
                overlay_offset, 1, s + byte_pos, char_len, col);
        }
        else
        {
            sdl_render_mono_utf8_glyph(font, cell_w, cell_h, origin_x, x, y,
                cell_offset, char_width, s + byte_pos, char_len, col);
            cell_offset += char_width;
        }

        byte_pos += char_len;
    }
}

static void sdl_render_story_text_free(sdl_view* d, TTF_Font* font, int x, int y, int n, const char* s,
    SDL_Color col)
{
    if (!d || !font || !s || n <= 0)
        return;

    char text_buf[256];
    int len = (n < 255) ? n : 255;
    len = utf8_safe_prefix_len(s, len);
    if (len <= 0)
        return;
    memcpy(text_buf, s, len);
    text_buf[len] = '\0';

    SDL_Surface* text_surface = TTF_RenderText_Blended(font, text_buf, 0, col);
    if (!text_surface)
        return;

    SDL_Texture* text_texture = SDL_CreateTextureFromSurface(g_state.renderer, text_surface);
    if (text_texture) {
        float cell_h_f = (float)d->cell_h;
        float surf_h_f = (float)text_surface->h;
        float scale = (surf_h_f > 0.0f) ? (cell_h_f / surf_h_f) : 1.0f;

        SDL_FRect dst = {
            (float)(x * d->cell_w),
            (float)(y * d->cell_h),
            (float)(text_surface->w) * scale,
            cell_h_f
        };

        float max_w = (float)(n * d->cell_w);
        if (dst.w > max_w) dst.w = max_w;

        SDL_SetTextureBlendMode(text_texture, SDL_BLENDMODE_BLEND);
        SDL_RenderTexture(g_state.renderer, text_texture, NULL, &dst);
        SDL_DestroyTexture(text_texture);
    }

    SDL_DestroySurface(text_surface);
}

static int sdl_render_story_text_free_px(sdl_view* d, TTF_Font* font, float x_px, int y, const char* s, int n,
    SDL_Color col, float max_w_px)
{
    if (!d || !font || !s || n <= 0)
        return 0;

    char text_buf[256];
    int len = (n < 255) ? n : 255;
    len = utf8_safe_prefix_len(s, len);
    if (len <= 0)
        return 0;
    for (int i = 0; i < len; i++)
    {
        unsigned char ch = (unsigned char)s[i];
        text_buf[i] = (ch ? (char)ch : ' ');
    }
    text_buf[len] = '\0';

    SDL_Surface* text_surface = TTF_RenderText_Blended(font, text_buf, 0, col);
    if (!text_surface)
        return 0;

    int adv_w_unscaled = 0;
    TTF_MeasureString(font, text_buf, len, 0, &adv_w_unscaled, NULL);

    float cell_h_f = (float)d->cell_h;
    float surf_h_f = (float)text_surface->h;
    float scale = (surf_h_f > 0.0f) ? (cell_h_f / surf_h_f) : 1.0f;
    float advance_w = (float)adv_w_unscaled * scale;
    float render_w = (float)text_surface->w * scale;

    if (max_w_px > 0.0f && render_w > max_w_px)
        render_w = max_w_px;
    if (max_w_px > 0.0f && advance_w > max_w_px)
        advance_w = max_w_px;

    SDL_Texture* text_texture = SDL_CreateTextureFromSurface(g_state.renderer, text_surface);
    if (text_texture)
    {
        SDL_FRect dst = {
            x_px,
            (float)(y * d->cell_h),
            render_w,
            cell_h_f
        };

        SDL_SetTextureBlendMode(text_texture, SDL_BLENDMODE_BLEND);
        SDL_RenderTexture(g_state.renderer, text_texture, NULL, &dst);
        SDL_DestroyTexture(text_texture);
    }

    SDL_DestroySurface(text_surface);
    return (int)advance_w;
}

static bool sdl_story_cell_is_text(byte a, char c)
{
    unsigned char uc = (unsigned char)c;

    /* High-bit attr/char pairs are tiles and are handled by pict hook. */
    if ((a & 0x80) && (uc & 0x80))
        return false;

    /* Bigtile second cell. */
    if (a == 255 && uc == 0xFF)
        return false;

    return true;
}

static byte sdl_ui_text_fg_attr(byte attr)
{
    return (attr >= TERM_UI_SELECTED) ? TERM_DARK : attr;
}

static byte sdl_ui_text_bg_attr(byte attr)
{
    return (attr >= TERM_UI_SELECTED)
        ? (byte)(attr - TERM_UI_SELECTED)
        : TERM_DARK;
}

static SDL_Color sdl_color_from_attr(byte attr)
{
    SDL_Color col = {
        angband_color_table[attr][1],
        angband_color_table[attr][2],
        angband_color_table[attr][3],
        255
    };

    return col;
}

static void sdl_fill_cell_span_with_attr(sdl_view* d, int x, int y, int n,
    byte attr)
{
    if (!d || n <= 0)
        return;

    SDL_Color bg = sdl_color_from_attr(sdl_ui_text_bg_attr(attr));
    SDL_FRect clear_rect = {
        x * (float)d->cell_w,
        y * (float)d->cell_h,
        n * (float)d->cell_w,
        (float)d->cell_h
    };

    SDL_SetRenderDrawColor(g_state.renderer, bg.r, bg.g, bg.b, bg.a);
    SDL_RenderFillRect(g_state.renderer, &clear_rect);
}

static void sdl_render_story_row_packed(sdl_view* d, TTF_Font* font, int y, const byte* story_row,
    const char* row_chars, const byte* row_attr)
{
    if (!d || !font || !Term || !story_row || !row_chars || !row_attr)
        return;

    const int wid = Term->wid;
    const float cell_w_f = (float)d->cell_w;

    int x = 0;
    while (x < wid)
    {
        /* Skip non-text cells (tiles) entirely to avoid clearing/overdrawing them. */
        if (!sdl_story_cell_is_text(row_attr[x], row_chars[x]))
        {
            x++;
            continue;
        }

        byte flags = story_row[x];
        bool use_story = (flags & STORY_FLAG_USE) != 0;
        bool grid_align = (flags & STORY_FLAG_CELL_ALIGN) != 0;
        byte attr = row_attr[x];

        int run_start = x;

        if (!use_story)
        {
            while (x < wid)
            {
                if (!sdl_story_cell_is_text(row_attr[x], row_chars[x]))
                    break;
                byte f = story_row[x];
                if ((f & STORY_FLAG_USE) != 0)
                    break;
                if (row_attr[x] != attr)
                    break;
                x++;
            }

            int run_len = x - run_start;
            SDL_Color col = sdl_color_from_attr(sdl_ui_text_fg_attr(attr));
            sdl_fill_cell_span_with_attr(d, run_start, y, run_len, attr);
            if (utf8_has_non_ascii_n(row_chars + run_start, run_len))
            {
                const char* font_path = config.monospace_font[0] != '\0'
                    ? config.monospace_font
                    : "lib/xtra/font/VictorMono-Medium.ttf";
                TTF_Font* mono_font = sdl_acquire_mono_font_cells(font_path,
                    d->cell_w, d->cell_h);

                if (mono_font)
                    sdl_render_mono_utf8_text_cells(d->font_atlas,
                        (d->font_atlas_cell_w > 0) ? d->font_atlas_cell_w : d->cell_w,
                        (d->font_atlas_cell_h > 0) ? d->font_atlas_cell_h : d->cell_h,
                        mono_font, (float)d->cell_w,
                        (float)d->cell_h, 0.0f, run_start, y, run_len,
                        row_chars + run_start, col);
                else
                    sdl_render_mono_text(d, run_start, y, run_len,
                        row_chars + run_start, col);
            }
            else
                sdl_render_mono_text(d, run_start, y, run_len, row_chars + run_start, col);
            continue;
        }

        if (grid_align)
        {
            while (x < wid)
            {
                if (!sdl_story_cell_is_text(row_attr[x], row_chars[x]))
                    break;
                byte f = story_row[x];
                if ((f & STORY_FLAG_USE) == 0)
                    break;
                if ((f & STORY_FLAG_CELL_ALIGN) == 0)
                    break;
                if (row_attr[x] != attr)
                    break;
                x++;
            }

            int run_len = x - run_start;
            SDL_Color col = sdl_color_from_attr(sdl_ui_text_fg_attr(attr));
            sdl_fill_cell_span_with_attr(d, run_start, y, run_len, attr);
            sdl_render_story_text_grid(d, font, run_start, y, run_len, row_chars + run_start, col);
            continue;
        }

        /* Free story region: pack segments by measured pixel width (including spaces). */
        while (x < wid)
        {
            if (!sdl_story_cell_is_text(row_attr[x], row_chars[x]))
                break;
            byte f = story_row[x];
            if ((f & STORY_FLAG_USE) == 0)
                break;
            if ((f & STORY_FLAG_CELL_ALIGN) != 0)
                break;
            x++;
        }

        int region_start = run_start;
        int region_end = x;
        if (region_end <= region_start)
            continue;

        int bg = region_start;
        while (bg < region_end)
        {
            byte bg_attr = row_attr[bg];
            int bg_end = bg + 1;

            while (bg_end < region_end && row_attr[bg_end] == bg_attr)
                bg_end++;

            sdl_fill_cell_span_with_attr(d, bg, y, bg_end - bg, bg_attr);
            bg = bg_end;
        }

        float px_cursor = region_start * cell_w_f;
        float px_end = region_end * cell_w_f;

        int seg = region_start;
        while (seg < region_end)
        {
            if (!sdl_story_cell_is_text(row_attr[seg], row_chars[seg]))
            {
                seg++;
                continue;
            }

            byte seg_attr = row_attr[seg];
            int seg_end = seg + 1;
            while (seg_end < region_end && sdl_story_cell_is_text(row_attr[seg_end], row_chars[seg_end])
                && row_attr[seg_end] == seg_attr)
            {
                seg_end++;
            }

            int seg_len = seg_end - seg;
            SDL_Color seg_col =
                sdl_color_from_attr(sdl_ui_text_fg_attr(seg_attr));

            float remaining = px_end - px_cursor;
            if (remaining <= 0.0f)
                break;

            int consumed = sdl_render_story_text_free_px(d, font, px_cursor, y, row_chars + seg, seg_len, seg_col,
                remaining);
            if (consumed <= 0)
                break;

            px_cursor += (float)consumed;
            seg = seg_end;
        }
    }
}

static void sdl_render_story_text_grid(sdl_view* d, TTF_Font* font, int x, int y, int n, const char* s,
    SDL_Color col)
{
    if (!d || !font || !s || n <= 0)
        return;

    if (utf8_has_non_ascii_n(s, n))
    {
        sdl_render_story_text_free(d, font, x, y, n, s, col);
        return;
    }

    float cell_w_f = (float)d->cell_w;
    float cell_h_f = (float)d->cell_h;

    for (int i = 0; i < n; i++) {
        Uint32 ch = (unsigned char)s[i];
        if (!ch || ch == ' ')
            continue;

        SDL_Surface* glyph_surface = TTF_RenderGlyph_Blended(font, ch, col);
        if (!glyph_surface)
            continue;

        SDL_Texture* glyph_texture = SDL_CreateTextureFromSurface(g_state.renderer, glyph_surface);
        if (glyph_texture) {
            float surf_w = (float)glyph_surface->w;
            float surf_h = (float)glyph_surface->h;
            float scale = (surf_h > 0.0f) ? (cell_h_f / surf_h) : 1.0f;
            float scaled_w = surf_w * scale;
            float dst_w = scaled_w;
            float offset_x = 0.0f;

            if (scaled_w > cell_w_f) {
                dst_w = cell_w_f;
                scale = (surf_w > 0.0f) ? (dst_w / surf_w) : 1.0f;
            } else {
                offset_x = (cell_w_f - scaled_w) * 0.5f;
            }

            SDL_FRect dst = {
                (float)((x + i) * d->cell_w) + offset_x,
                (float)(y * d->cell_h),
                dst_w,
                cell_h_f
            };

            SDL_SetTextureBlendMode(glyph_texture, SDL_BLENDMODE_BLEND);
            SDL_RenderTexture(g_state.renderer, glyph_texture, NULL, &dst);
            SDL_DestroyTexture(glyph_texture);
        }

        SDL_DestroySurface(glyph_surface);
    }
}

